  `design_type_` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'simple 简单模式 advanced 复杂模式',
  `group_code_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类字典编码',
  `ds_key_` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数据源别名',
  `init_query_` tinyint(4) NULL DEFAULT NULL COMMENT '是否默认查询',
