  `sql_content_` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SQL',
  `conditions_` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '查询列表',
  `sql_table_list_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '表列表',
  `buttons_` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '按钮列表',
  `choose_type_` tinyint(4) NULL DEFAULT NULL COMMENT '单选多选',
  `show_rows_num_` tinyint(4) NULL DEFAULT NULL COMMENT '显示行号 0:否,1:是',
