  `pk_name_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主键名称',
  `left_tree_` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '左树配置',
  `extend_conf_` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展配置',
  `app_conf_` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'app配置',
  `related_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '表单KEY/流程定义id',
  `max_export_rows_` int(11) NULL DEFAULT NULL COMMENT '最大导出行数',
