  `type_code_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '系统树编码',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `index_code`(`code_`) USING BTREE
