-- Table structure for bpm_bytearray
-- ----------------------------
DROP TABLE IF EXISTS `bpm_bytearray`;
CREATE TABLE `bpm_bytearray`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `category_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类别',
  `bytes_` longblob NULL COMMENT '字节数据',
  PRIMARY KEY (`id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'BPM字节数组' ROW_FORMAT = Dynamic;

