-- ----------------------------
-- Table structure for bpm_definition
-- ----------------------------
DROP TABLE IF EXISTS `bpm_definition`;
CREATE TABLE `bpm_definition`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `name_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名字',
  `key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程KEY',
  `desc_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述',
  `ACT_DEF_ID_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Activiti 定义ID',
  `ACT_MODEL_ID_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Activiti 模型ID',
  `ACT_DEPLOY_ID_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Activiti 部署ID',
  `status_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态',
  `version_` int(11) NULL DEFAULT NULL COMMENT '版本号',
  `support_mobile_` tinyint(4) NULL DEFAULT 0 COMMENT '是否支持移动端',
  `is_main_` tinyint(4) NULL DEFAULT NULL COMMENT '是否主版本',
  `icon_style_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ICON配置',
  `hidden_` tinyint(4) NULL DEFAULT 0 COMMENT '是否隐藏，默认否，隐藏后将不在个人办公-发起申请页面展示，但依然可以通过其他方式发起流程',
  `sn_` int(11) NULL DEFAULT 10 COMMENT 'SN排序',
  `type_code_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类字典KEY',
  `process_editor_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程设计器',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `create_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `create_org_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属组织',
  `update_time_` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `updater_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `rev_` int(11) NULL DEFAULT NULL COMMENT '乐观锁',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `bpm_process_def_key`(`key_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '流程定义' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of bpm_definition
-- ----------------------------

-- ----------------------------
-- Table structure for bpm_instance
-- ----------------------------
DROP TABLE IF EXISTS `bpm_instance`;
CREATE TABLE `bpm_instance`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `title_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `def_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '定义ID',
  `ACT_INST_ID_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Activiti实例ID',
  `parent_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父实例Id',
  `def_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程Key',
  `biz_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务ID',
  `status_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态',
  `duration_ms_` bigint(20) NULL DEFAULT NULL COMMENT '持续时间',
  `support_mobile_` tinyint(4) NULL DEFAULT 0 COMMENT '是否支持移动端',
  `suspension_state_` tinyint(4) NULL DEFAULT NULL COMMENT '挂起状态',
  `super_task_def_key_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父流程定义节点KEY',
  `calling_convention_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调用约定',
  `type_code_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类字典KEY',
  `summary_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程概要',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `end_time_` datetime(0) NULL DEFAULT NULL COMMENT '完成时间',
  `creator_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `create_org_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属组织',
  `update_time_` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `updater_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `rev_` int(11) NULL DEFAULT NULL COMMENT '乐观锁',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `idx_inst_ACT_INST_ID_`(`ACT_INST_ID_`) USING BTREE,
  INDEX `idx_inst_parent_id_`(`parent_id_`) USING BTREE,
  INDEX `idx_inst_biz_key_`(`biz_id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实例' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of bpm_instance
-- ----------------------------

-- ----------------------------
-- Table structure for bpm_plugin_ensure_candidate
-- ----------------------------
DROP TABLE IF EXISTS `bpm_plugin_ensure_candidate`;
CREATE TABLE `bpm_plugin_ensure_candidate`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `inst_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实例 ID',
  `node_key_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务KEY',
  `task_name_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务名',
  `identities_` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '候选人JSON',
  `node_type_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '节点类型',
  `skip_reason_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '跳过原因',
  `is_skip_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否跳过',
  `distnation_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目标节点，如果存在则跳转',
  `is_force_update_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否强制更新',
  `is_dynamic_task_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否动态任务',
  `create_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `updater_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_org_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属组织',
  `update_time_` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人ID',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `ensure_candidate_inst_id_idx`(`inst_id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '明确候选人插件' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_plugin_reminder_log
-- ----------------------------
DROP TABLE IF EXISTS `bpm_plugin_reminder_log`;
CREATE TABLE `bpm_plugin_reminder_log`  (
  `id_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `instance_id_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实例ID',
  `reminder_title_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办标题',
  `title_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程标题',
  `task_def_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务定义KEY',
  `msg_type_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办消息类型',
  `reminder_users_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办人',
  `reminder_userids_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办人ID',
  `reminder_date_` datetime(0) NULL DEFAULT NULL COMMENT '催办时间',
  `supervisor_names_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '督办人',
  `supervisor_ids_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '督办人Id',
  `reminder_type_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办类型',
  `flow_operate_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程操作',
  `receiver_names_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '转办人',
  `receiver_ids_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '转办人ids',
  `extend_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他说明',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '流程催办日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_plugin_reminder_trigger
-- ----------------------------
DROP TABLE IF EXISTS `bpm_plugin_reminder_trigger`;
CREATE TABLE `bpm_plugin_reminder_trigger`  (
  `id_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `task_id_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务ID',
  `reminder_desc_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办的描述',
  `before_script_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办前置脚本',
  `msg_type_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办消息类型',
  `html_msg_` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'html消息',
  `text_msg_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '普通消息',
  `template_code_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息模板编码',
  `is_calc_workday_` tinyint(4) NULL DEFAULT NULL COMMENT '是否工作日计算',
  `is_urgent_` tinyint(4) NULL DEFAULT NULL COMMENT '是否加急任务',
  `max_reminder_times` int(11) NULL DEFAULT NULL COMMENT '最多催办次数',
  `reminder_times_` int(11) NULL DEFAULT NULL COMMENT '催办次数',
  `reminder_cycle_` int(11) NULL DEFAULT NULL COMMENT '催办周期',
  `duedate_` datetime(0) NOT NULL COMMENT '到期时间',
  `retries_` tinyint(4) NULL DEFAULT NULL COMMENT '重试次数',
  `version_` tinyint(4) NULL DEFAULT NULL COMMENT '版本号',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time_` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `exception_id_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常ID',
  `lock_expire_at_` datetime(0) NULL DEFAULT NULL COMMENT '持锁到期时间，用于并发催办处理',
  `lock_machine_at_` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '持锁机器',
  `exception_msg_` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常信息',
  `reminder_type_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '催办类型：msg（发送消息），taskTurn（任务转办），flowOperate（流程操作），',
  `receiver_` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '转办接收人',
  `supervise_template_code_` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '督办消息模板code',
  `supervisor_` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '督办人',
  `flow_operate_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程操作： turn 转办，skip 跳过当前任务，end 结束流程',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `task_id_`(`task_id_`) USING BTREE,
  INDEX `duedate_`(`duedate_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '流程催办触发' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_plugin_sign
-- ----------------------------
DROP TABLE IF EXISTS `bpm_plugin_sign`;
CREATE TABLE `bpm_plugin_sign`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `inst_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实例id',
  `task_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务id',
  `setting_` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置json信息',
  `progress_` int(11) NULL DEFAULT NULL COMMENT '进度信息，下标',
  `node_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '节点KEY',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `create_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_org_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属组织',
  `updater_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time_` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `identitis_` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '候选人列表json信息',
  PRIMARY KEY (`id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '会签插件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_schedule_start_log
-- ----------------------------
DROP TABLE IF EXISTS `bpm_schedule_start_log`;
CREATE TABLE `bpm_schedule_start_log`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `start_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程定时启动ID',
  `def_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程定义KEY',
  `def_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程定义ID',
  `inst_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流程实例ID',
  `successful_` tinyint(3) UNSIGNED NOT NULL COMMENT '执行成功',
  `exception_stack_` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '异常堆栈',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `start_id_`(`start_id_`) USING BTREE,
  INDEX `def_id_`(`def_id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '流程定时启动日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_task
-- ----------------------------
DROP TABLE IF EXISTS `bpm_task`;
CREATE TABLE `bpm_task`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `name_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名字',
  `node_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务KEY',
  `title_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题-冗余',
  `inst_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '实例ID',
  `ACT_TASK_ID_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Activiti 任务ID',
  `ACT_EXECUTION_ID_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Activiti 执行id',
  `def_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '定义ID',
  `status_arr_` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '状态列表',
  `suspension_state_` tinyint(4) NULL DEFAULT NULL COMMENT '挂起状态',
  `assignee_names_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务执行人说明',
  `priority_` tinyint(4) NULL DEFAULT 50 COMMENT '紧急程度',
  `support_mobile_` tinyint(4) NULL DEFAULT 0 COMMENT '是否支持移动端',
  `back_node_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回后返回节点',
  `due_time_` datetime(0) NULL DEFAULT NULL COMMENT '到期时间',
  `task_type_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务类型',
  `parent_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父任务ID',
  `type_code_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类编码',
  `create_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `create_org_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属组织',
  `updater_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time_` datetime(6) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `create_time_` datetime(3) NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `idx_task_instid`(`inst_id_`) USING BTREE,
  INDEX `idx_task_parentid`(`parent_id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_task_discuss
-- ----------------------------
DROP TABLE IF EXISTS `bpm_task_discuss`;
CREATE TABLE `bpm_task_discuss`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `inst_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程实例ID',
  `opinion_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批ID',
  `task_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务定义Key',
  `task_name_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务名称',
  `content_` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评论内容',
  `type_` tinyint(4) NULL DEFAULT 1 COMMENT '类型：0:提交，1：附言，2：评论，3：点赞',
  `secret_` tinyint(1) NULL DEFAULT 0 COMMENT '是否私密：0:否，1：是',
  `attachment_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `create_by_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人id',
  `creator_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `idx_discuss_opinion`(`opinion_id_`) USING BTREE,
  INDEX `idx_discuss_instId`(`inst_id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务谈论记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_task_duration_statistics
-- ----------------------------
DROP TABLE IF EXISTS `bpm_task_duration_statistics`;
CREATE TABLE `bpm_task_duration_statistics`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `def_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '定义ID',
  `task_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '节点标识',
  `duration` bigint(20) NULL DEFAULT NULL COMMENT '平均耗时，单位是毫秒',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id_`) USING BTREE,
  UNIQUE INDEX `def_id_`(`def_key_`, `task_key_`) USING BTREE,
  INDEX `def_id_idx`(`def_key_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '流程节点耗时统计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_task_identitylink
-- ----------------------------
DROP TABLE IF EXISTS `bpm_task_identitylink`;
CREATE TABLE `bpm_task_identitylink`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `task_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务ID',
  `inst_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '实例ID',
  `identity_type_` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '候选人类型',
  `identity_name_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名字',
  `identity_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '候选人ID',
  `permission_code_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '候选人编码',
  `status_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'default' COMMENT '状态（lock锁定,agency代理,default）lock状态',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `idx_identitylink_instid`(`inst_id_`, `task_id_`) USING BTREE,
  INDEX `idx_permission_code_`(`permission_code_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务候选人' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for bpm_task_opinion
-- ----------------------------
DROP TABLE IF EXISTS `bpm_task_opinion`;
CREATE TABLE `bpm_task_opinion`  (
  `id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ID',
  `inst_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程实例ID',
  `ACT_EXECUTION_ID_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ACT执行栈',
  `task_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务ID',
  `task_def_key_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务定义Key',
  `task_type_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务类型',
  `task_name_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务名称',
  `assign_info_` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务分配情况',
  `approver_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批人',
  `approver_org_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批人组织ID',
  `approver_name_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批人名字',
  `approve_time_` datetime(3) NULL DEFAULT NULL COMMENT '审批时间',
  `opinion_` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '意见',
  `status_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '状态',
  `trace_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '意见线路',
  `parent_task_id_` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父任务ID',
  `attachment_` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `duration_ms_` bigint(20) NULL DEFAULT NULL COMMENT '持续时间',
  `due_time_` datetime(0) NULL DEFAULT NULL COMMENT '到期时间',
  `create_by_` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time_` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id_`) USING BTREE,
  INDEX `idx_opinion_task`(`task_id_`) USING BTREE,
  INDEX `idx_opinion_approver`(`approver_`) USING BTREE,
  INDEX `idx_opinion_instId`(`inst_id_`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务审批记录' ROW_FORMAT = Dynamic;

