-- ----------------------------
-- Table structure for crm_businessopportunity
-- ----------------------------
DROP TABLE IF EXISTS `crm_businessopportunity`;
CREATE TABLE `crm_businessopportunity`  (
  `id_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `customer_name_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户id',
  `customer_contact_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户联系人',
  `opportunity_name_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商机名称',
  `sales_phase_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售阶段',
  `responsible_person_` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '负责人',
  `total_amount_` decimal(50, 0) NULL DEFAULT NULL COMMENT '合计总额',
  `discount_` decimal(50, 0) NULL DEFAULT NULL COMMENT '折扣',
