-- ----------------------------
-- View structure for bpm_instance_view
-- ----------------------------
DROP VIEW IF EXISTS `bpm_instance_view`;
CREATE ALGORITHM = UNDEFINED DEFINER = `root`@`localhost` SQL SECURITY DEFINER VIEW `bpm_instance_view` AS select `bpm_definition`.`id_` AS `id_`,`bpm_definition`.`name_` AS `name_`,`bpm_definition`.`key_` AS `key_`,`bpm_definition`.`desc_` AS `desc_`,`sys_connect_record`.`target_id_` AS `target_id_`,`biz_form`.`name_` AS `form_name_`,`biz_form`.`bo_code_` AS `bo_code_` from ((`bpm_definition` left join `sys_connect_record` on((`bpm_definition`.`id_` = `sys_connect_record`.`source_id_`))) left join `biz_form` on((`sys_connect_record`.`target_id_` = `biz_form`.`code_`))) where ((`sys_connect_record`.`type_` = 'BPM-DEF-FORM') and (`bpm_definition`.`is_main_` = 1) and (`sys_connect_record`.`target_id_` like '%_pc'));

-- ----------------------------
-- View structure for crm_shangjichaxun
-- ----------------------------
DROP VIEW IF EXISTS `crm_shangjichaxun`;
CREATE ALGORITHM = UNDEFINED DEFINER = `root`@`localhost` SQL SECURITY DEFINER VIEW `crm_shangjichaxun` AS select `crm_customerinformation`.`customer_name_` AS `customer_name_`,`crm_businessopportunity`.`customer_name_` AS `customerNameID`,`crm_businessopportunity`.`customer_contact_` AS `customer_contact_`,`crm_businessopportunity`.`opportunity_name_` AS `opportunity_name_`,`crm_businessopportunity`.`id_` AS `opportunity_id_`,`crm_businessopportunity`.`total_amount_` AS `total_amount_`,`crm_businessopportunity`.`discount_` AS `discount_`,`crm_businessopportunity`.`final_price_` AS `final_price_`,`crm_businessopportunity`.`responsible_person_` AS `负责人`,`crm_customerinformation`.`customernumber_` AS `客户编号` from (`crm_customerinformation` join `crm_businessopportunity` on((`crm_customerinformation`.`id_` = `crm_businessopportunity`.`customer_name_`)));

-- ----------------------------
-- View structure for crm_shangji_mingxi
-- ----------------------------
DROP VIEW IF EXISTS `crm_shangji_mingxi`;
CREATE ALGORITHM = UNDEFINED DEFINER = `root`@`localhost` SQL SECURITY DEFINER VIEW `crm_shangji_mingxi` AS select `crm_customerinformation`.`customer_name_` AS `customer_name_`,`crm_productdetails`.`product_name_` AS `product_name_`,`crm_productdetails`.`specification_and_model_` AS `specification_and_model_`,`crm_productdetails`.`unit_` AS `unit_`,`crm_productdetails`.`price_` AS `price_`,`crm_productdetails`.`quantity_` AS `quantity_`,`crm_productdetails`.`discount_` AS `discount_`,`crm_productdetails`.`subtotal_` AS `subtotal_`,`crm_productdetails`.`customer_name_` AS `customer_name_ID` from (`crm_customerinformation` join `crm_productdetails` on((`crm_customerinformation`.`id_` = `crm_productdetails`.`customer_name_`)));

-- ----------------------------
-- View structure for crm_xuanlianxiren
-- ----------------------------
DROP VIEW IF EXISTS `crm_xuanlianxiren`;
CREATE ALGORITHM = UNDEFINED DEFINER = `root`@`localhost` SQL SECURITY DEFINER VIEW `crm_xuanlianxiren` AS select `crm_customerinformation`.`id_` AS `id_`,`crm_customerinformation`.`customer_name_` AS `customer_name_`,`crm_contactinformation`.`enterprise_name_` AS `enterprise_name_`,`crm_contactinformation`.`contact_name_` AS `contact_name_`,`crm_contactinformation`.`mobile_phone_number_` AS `mobile_phone_number_`,`crm_contactinformation`.`department_` AS `department_`,`crm_contactinformation`.`post_` AS `post_`,`crm_contactinformation`.`wechat_signal_` AS `wechat_signal_`,`crm_contactinformation`.`mailbox_` AS `mailbox_`,`crm_contactinformation`.`decision_maker_or_not_` AS `decision_maker_or_not_`,`crm_customerinformation`.`responsibleperson_` AS `responsibleperson_` from (`crm_customerinformation` join `crm_contactinformation`) where (`crm_customerinformation`.`id_` = `crm_contactinformation`.`enterprise_name_`);

SET FOREIGN_KEY_CHECKS = 1;
