INSERT INTO `ab_message_template` VALUES ('1602918114232172642', 'copy_template', NULL, '抄送模板', '系统默认抄送模板', '<p><span style=\"background-color: rgb(245, 247, 249); color: rgb(103, 106, 108);\">​您好，请有新的流程抄送：</span>${title}<span style=\"background-color: rgb(245, 247, 249); color: rgb(103, 106, 108);\"> ！</span></p>', '{\"cardTitle\":\"\",\"cardUrl\":\"\",\"cardContent\":\"\",\"htmlTemplate\":\"undefined${subject}${subject}\"}', '', '[{\"key\":\"title\",\"value\":\"${bpmInstance.title}\"}]', NULL, NULL, 1, NULL, '2022-12-14 14:47:09', '1', '', '2022-12-14 14:47:09', '系统管理员', '1');
INSERT INTO `ab_message_template` VALUES ('1602918114232172647', 'node_message_template', NULL, '流程节点通知消息模板', '流程节点通知消息模板', '<p><span style=\"background-color: rgb(245, 247, 249); color: rgb(103, 106, 108);\">流程消息：</span>${title}<span style=\"background-color: rgb(245, 247, 249); color: rgb(103, 106, 108);\"> ！</span></p>', '{\"cardTitle\":\"代办任务：${title} ！\",\"cardUrl\":\"${appUrl}/bpm/bpmTaskComplate?id=${taskId}\",\"cardContent\":\"代办任务：${title} ！\",\"htmlTemplate\":\"undefined${subject}${subject}${subject}\"}', '', '[{\"key\":\"title\",\"value\":\"${bpmInstance.title}\"},{\"key\":\"appUrl\",\"value\":\"http://osscqkead4.a5.tongzhouyun.com/#\"},{\"key\":\"taskId\",\"value\":\"${bpmTask.id}\"}]', NULL, NULL, 1, NULL, '2022-12-14 14:47:09', '1', '', '2023-05-19 17:12:28', '系统管理员', '1602918114232172634');
INSERT INTO `ab_message_template` VALUES ('1602918114232172653', 'reminder_template', NULL, '催办消息模板', '流程默认催办消息模板', '<p><span style=\"background-color: rgb(245, 247, 249); color: rgb(103, 106, 108);\">​您好，请您尽快处理任务：</span>${title}<span style=\"background-color: rgb(245, 247, 249); color: rgb(103, 106, 108);\">！</span></p>', '{\"cardTitle\":\"催办任务：${title} ！\",\"cardUrl\":\"${appUrl}/bpm/bpmTaskComplate?id=${taskId}\",\"cardContent\":\"催办任务：${title} ！\"}', '', '[{\"key\":\"title\",\"value\":\"${bpmInstance.title} \"},{\"key\":\"appUrl\",\"value\":\"http://osscqkead4.a5.tongzhouyun.com/#\"},{\"key\":\"taskId\",\"value\":\"${bpmTask.id}\"}]', NULL, NULL, 1, NULL, '2022-12-14 14:47:09', '1', '', '2023-05-19 17:19:19', '系统管理员', '1602918114232172634');
INSERT INTO `ab_message_template` VALUES ('1602918114232172657', 'taskTurnMsg', NULL, '任务转办消息', '流程任务转办默认消息模板', '<p>您有一条新的转办任务，请及时办理。&nbsp;转办备注为：${转办备注}。</p><p>流程标题为：${流程标题}</p>', '{\"cardTitle\":\"\",\"cardUrl\":\"\",\"cardContent\":\"\"}', '', '[{\"key\":\"转办备注\",\"value\":\"${opinion}\"},{\"key\":\"流程标题\",\"value\":\"${bpmInstance.title}\"}]', NULL, NULL, 1, NULL, '2022-12-14 14:47:09', '1', '', '2022-12-14 14:47:09', '系统管理员', '1');
INSERT INTO `ab_message_template` VALUES ('1602918114232172668', 'news_message_template', NULL, '新闻消息模板', '新闻模块的消息模板', '<p>您收到一条${type}通知：${subject} ,望查阅。</p><p>发送人：${senderName}</p><p>发送时间 ：${sendTime}</p>', '{\"cardTitle\":\"\",\"cardUrl\":\"\",\"cardContent\":\"\"}', '', '[{\"key\":\"title\",\"value\":\"新闻-${title}\"},{\"key\":\"subject\",\"value\":\"${subject}\"},{\"key\":\"senderName\",\"value\":\"${senderName} \"},{\"key\":\"sendTime\",\"value\":\"${sendTime}\"}]', NULL, NULL, 1, NULL, '2022-12-14 14:47:09', '1', '', '2022-12-14 14:47:09', '系统管理员', '1');
