INSERT INTO `ab_message_template` VALUES ('1602918114232172689', 'notify_message_template', NULL, '公告消息模板', '公告模块的消息模板', '<p>您收到一条${type}通知：${subject} ,望查阅。</p><p>发送人：${senderName}</p><p>发送时间 ：${sendTime}</p>', '{\"cardTitle\":\"\",\"cardUrl\":\"\",\"cardContent\":\"\"}', '', '[{\"key\":\"title\",\"value\":\"公告-${title}\"},{\"key\":\"subject\",\"value\":\"${subject}\"},{\"key\":\"senderName\",\"value\":\"${senderName}\"},{\"key\":\"sendTime\",\"value\":\"${sendTime}\"}]', NULL, NULL, 1, NULL, '2022-12-14 14:47:09', '1', '', '2022-12-14 14:47:09', '系统管理员', '1');
