INSERT INTO `ab_message_template` VALUES ('1672860345298386944', 'sys_error_msg_template', NULL, '系统异常消息模板', '系统异常消息推送模板', '<p>用户：${用户名}（${用户账号}）,系统操作异常。</p><p>异常信息为：${错误信息}</p><p>出现时间：${时间}</p><p>ip归属地：${ip归属地}（${ip}）</p><p>请关注：${接口路径}</p><p><br></p><p><br></p><p><br></p>', '{\"cardTitle\":\"系统异常告警\",\"cardUrl\":\"${appUrl}/sys/logErr/listJson\",\"cardContent\":\"用户：${用户名}（${用户账号}）,系统操作异常。\\n异常信息为：${错误信息}\\n出现时间：${时间}\\nip归属地：${ip归属地}（${ip}）\\n请关注：${接口路径}\"}', '', '[{\"key\":\"用户名\",\"value\":\"${fullName}\"},{\"key\":\"用户账号\",\"value\":\"${account}\"},{\"key\":\"错误信息\",\"value\":\"${content}\"},{\"key\":\"时间\",\"value\":\"${createTime}\"},{\"key\":\"ip归属地\",\"value\":\"${ipAddress}\"},{\"key\":\"ip\",\"value\":\"${ip}\"},{\"key\":\"接口路径\",\"value\":\"${path}\"},{\"key\":\"appUrl\",\"value\":\"http://test.a5.tongzhouyun.com/app/#\"}]', NULL, NULL, 1, NULL, '2023-06-25 14:52:41', '1602918114232172634', '1639155804422721536', '2023-06-25 16:09:33', '系统管理员', '1602918114232172634');
