INSERT INTO `biz_form` VALUES ('1809123583503499264', 'pc', 'zcgl_zccwxx_pc', '资产财务信息', 'zcgl', 'zcgl_zccwxx', 'elementFlowDesign', 'zcgl_zcxx', '资产信息', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-card style=\"margin-bottom: 15px;width: 100%;\" shadow=\"hover\">\n		<template #header>\n			<span class=\"title\">财务信息</span>\n		</template>\n		<ab-form-group>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"单价\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.price\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.price\" placeholder=\"请输入单价\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.price\" :rules=\"[{\'pattern\':\'^-?((\\\\d{1,3}(,\\\\d{3})+?|\\\\d+)(\\\\.\\\\d{1,5})?)$\',\'message\':\'只能输入数字\'},{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-单价\"></ab-input>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"购入数量\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.counts\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.counts\" placeholder=\"请输入购入数量\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.counts\" :rules=\"[{\'pattern\':\'^-?((\\\\d{1,3}(,\\\\d{3})+?|\\\\d+)(\\\\.\\\\d{1,5})?)$\',\'message\':\'只能输入数字\'},{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-购入数量\"></ab-input>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"总金额（元）\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.amount\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.amount\" placeholder=\"请输入原金额（元）\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.amount\" :rules=\"[{\'pattern\':\'^-?((\\\\d{1,3}(,\\\\d{3})+?|\\\\d+)(\\\\.\\\\d{1,5})?)$\',\'message\':\'只能输入数字\'},{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-总金额（元）\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"入账状态\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.entryStatus\">\n				<ab-radio-group v-model=\"data.zcgl_zcxx.zcgl_zccw.entryStatus\" placeholder=\"请输入入账状态\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.entryStatus\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-入账状态\" dic-code=\"zcgl_rzxs\"></ab-radio-group>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"财务入账日期\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.entryDate\">\n				<ab-date v-model=\"data.zcgl_zcxx.zcgl_zccw.entryDate\" placeholder=\"请输入财务入账日期\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.entryDate\" :rules=\"[]\" desc=\"资产管理_资产财务-财务入账日期\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"会计凭证号\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.accDocNo\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.accDocNo\" placeholder=\"请输入会计凭证号\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.accDocNo\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-会计凭证号\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"价值类型\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.valueType\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.valueType\" placeholder=\"请输入价值类型\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.valueType\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-价值类型\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"资金来源\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.fundsSrc\">\n				<ab-tree-select v-model=\"data.zcgl_zcxx.zcgl_zccw.fundsSrc\" placeholder=\"请输入资金来源\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.fundsSrc\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-资金来源\" dic-code=\"zcgl_zjly\" :multiple=\"false\"></ab-tree-select>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"财政拨款（元）\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.fiscalAllotment\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.fiscalAllotment\" placeholder=\"请输入财政拨款（元）\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.fiscalAllotment\" :rules=\"[{\'pattern\':\'^-?((\\\\d{1,3}(,\\\\d{3})+?|\\\\d+)(\\\\.\\\\d{1,5})?)$\',\'message\':\'只能输入数字\'},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-财政拨款（元）\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"非财政拨款（元）\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.noneFiscalAllotment\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.noneFiscalAllotment\" placeholder=\"请输入非财政拨款（元）\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.noneFiscalAllotment\" :rules=\"[{\'pattern\':\'^-?((\\\\d{1,3}(,\\\\d{3})+?|\\\\d+)(\\\\.\\\\d{1,5})?)$\',\'message\':\'只能输入数字\'},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-非财政拨款（元）\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n		</ab-form-group>\n	</ab-card>\n	<ab-card style=\"margin-bottom: 15px;width: 100%;\" shadow=\"hover\">\n		<template #header>\n			<span class=\"title\">资产信息</span>\n		</template>\n		<ab-form-group>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"资产名称\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.name\">\n				<ab-input v-model=\"data.zcgl_zcxx.name\" placeholder=\"请输入资产名称\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.name\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-资产名称\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"资产分类\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.typeId\">\n				<ab-data-selector v-model=\"data.zcgl_zcxx.typeId\" placeholder=\"请输入资产分类\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.typeId\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-资产分类\" :disabled=\"true\" dialog-key=\"zcgl_zcfl\" label-field=\"name\" value-field=\"id_\" select-type=\"custom\" param=\"id_\" icon=\"org\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"入库编号\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.code\">\n				<ab-serial-no v-model=\"data.zcgl_zcxx.code\" placeholder=\"请输入编号\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.code\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-入库编号\" :disabled=\"true\" serial-no-code=\"zcgl_rkbh\"></ab-serial-no>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"采购组织形式\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.purchaseWay\">\n				<ab-tree-select v-model=\"data.zcgl_zcxx.purchaseWay\" placeholder=\"请输入采购组织形式\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.purchaseWay\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-采购组织形式\" :disabled=\"true\" dic-code=\"zcgl_cgzzxs\" :multiple=\"false\"></ab-tree-select>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"取得方式\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.getWay\">\n				<ab-tree-select v-model=\"data.zcgl_zcxx.getWay\" placeholder=\"请输入取得方式\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.getWay\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-取得方式\" :disabled=\"true\" dic-code=\"zcgl_qdfs\" :multiple=\"false\"></ab-tree-select>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"取得日期\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.getDate\">\n				<ab-date v-model=\"data.zcgl_zcxx.getDate\" placeholder=\"请输入取得日期\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.getDate\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产信息-取得日期\" :disabled=\"true\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"计量单位\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.unit\">\n				<ab-tree-select v-model=\"data.zcgl_zcxx.unit\" placeholder=\"请输入计量单位\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.unit\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-计量单位\" :disabled=\"true\" dic-code=\"zcgl_jldw\" :multiple=\"false\"></ab-tree-select>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"设备用途\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.purpose\">\n				<ab-tree-select v-model=\"data.zcgl_zcxx.purpose\" placeholder=\"请输入设备用途\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.purpose\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-设备用途\" :disabled=\"true\" dic-code=\"zcgl_sbyt\" :multiple=\"false\"></ab-tree-select>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"品牌\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.brandName\">\n				<ab-input v-model=\"data.zcgl_zcxx.brandName\" placeholder=\"请输入品牌\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.brandName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-品牌\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"规格型号\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.specification\">\n				<ab-input v-model=\"data.zcgl_zcxx.specification\" placeholder=\"请输入规格型号\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.specification\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-规格型号\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"生产厂家\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.manufacturer\">\n				<ab-input v-model=\"data.zcgl_zcxx.manufacturer\" placeholder=\"请输入生产厂家\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.manufacturer\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-生产厂家\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"销售商\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.vendor\">\n				<ab-input v-model=\"data.zcgl_zcxx.vendor\" placeholder=\"请输入销售商\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.vendor\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-销售商\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"关联地址\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.location\">\n				<ab-data-selector v-model=\"data.zcgl_zcxx.location\" placeholder=\"请输入关联地址\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.location\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-关联地址\" :disabled=\"true\" dialog-key=\"zcgl_zcsyd\" label-field=\"name\" value-field=\"id\" select-type=\"custom\" param=\"id_\" icon=\"com\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"合同编号\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.contractNo\">\n				<ab-input v-model=\"data.zcgl_zcxx.contractNo\" placeholder=\"请输入合同编号\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.contractNo\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-合同编号\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"投入使用日期\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useDate\">\n				<ab-date v-model=\"data.zcgl_zcxx.useDate\" placeholder=\"请输入投入使用日期\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useDate\" :rules=\"[]\" desc=\"资产管理_资产信息-投入使用日期\" :disabled=\"true\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"保修截止日期\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.warrantyExpired\">\n				<ab-date v-model=\"data.zcgl_zcxx.warrantyExpired\" placeholder=\"请输入保修截止日期\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.warrantyExpired\" :rules=\"[]\" desc=\"资产管理_资产信息-保修截止日期\" :disabled=\"true\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n			</ab-form-item>\n			<ab-form-item :span=\"24\" label=\"附加信息\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.extraInfo\">\n				<ab-input v-model=\"data.zcgl_zcxx.extraInfo\" placeholder=\"请输入附加信息\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.extraInfo\" :rules=\"[]\" desc=\"资产管理_资产信息-附加信息\" :disabled=\"true\" type=\"textarea\" rows=\"2\"></ab-input>\n			</ab-form-item>\n			<ab-card style=\"margin-bottom: 15px;width: 100%\" shadow=\"hover\" body-style=\"overflow:auto\" v-ab-permission=\"tablePermission.zcgl_zcxx.zcgl_type_rel\">\n				<template #header>\n					<span class=\"title\">资产属性</span>\n					<ab-sub-load v-model=\"data.zcgl_zcxx\" table-path=\"zcgl_type_relList\" bo-code=\"zcgl_zcxx\" :permission-type=\"permissionType\" :permission-value=\"permissionValue\" :permission=\"tablePermission.zcgl_zcxx.zcgl_type_rel\" fk=\"id\"></ab-sub-load>\n				</template>\n				<table class=\"ab-table\">\n					<thead>\n						<tr>\n							<th v-ab-permission=\"permission.zcgl_zcxx.zcgl_type_rel.name\" ><ab-required :permission=\"permission.zcgl_zcxx.zcgl_type_rel.name\"></ab-required>属性名称</th>\n							<th v-ab-permission=\"permission.zcgl_zcxx.zcgl_type_rel.val\" ><ab-required :permission=\"permission.zcgl_zcxx.zcgl_type_rel.val\"></ab-required>属性值</th>\n							<th>操作</th>\n						</tr>\n					</thead>\n					<tbody>\n						<ab-sub-tr-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.zcgl_zcxx.zcgl_type_rel\" :table-permission=\"tablePermission\" v-for=\"(zcgl_type_rel,index) in data.zcgl_zcxx.zcgl_type_relList\" :key=\"zcgl_type_rel.$$abHashCode\">\n							<td v-ab-permission=\"permission.zcgl_zcxx.zcgl_type_rel.name\">\n								<ab-input v-model=\"zcgl_type_rel.name\" placeholder=\"请输入属性名称\" :permission=\"scopePermission.name\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'资产分类属性关联-属性名称【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n							</td>\n							<td v-ab-permission=\"permission.zcgl_zcxx.zcgl_type_rel.val\">\n								<ab-input v-model=\"zcgl_type_rel.val\" placeholder=\"请输入属性值\" :permission=\"scopePermission.val\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'资产分类属性关联-属性值【第\'+(index+1)+\'条】\'\"></ab-input>\n							</td>\n							<td>\n								<ab-button-group>\n								</ab-button-group>\n							</td>\n						</ab-sub-tr-scope>\n					</tbody>\n				</table>\n			</ab-card>\n		</ab-form-group>\n	</ab-card>\n</ab-form-group>\n<abTablePlugins>\n	<ab-calculate v-model=\"data.zcgl_zcxx.zcgl_zccw.amount\" :script=\"abGetNumber(data.zcgl_zcxx.zcgl_zccw.price)*abGetNumber(data.zcgl_zcxx.zcgl_zccw.counts)\" desc=\"计算总金额\" :decimals=\"2\"></ab-calculate><ab-calculate v-model=\"data.zcgl_zcxx.zcgl_zccw.noneFiscalAllotment\" :script=\"abGetNumber(data.zcgl_zcxx.zcgl_zccw.amount)-abGetNumber(data.zcgl_zcxx.zcgl_zccw.fiscalAllotment)\" desc=\"赋值非拨款\" :decimals=\"2\"></ab-calculate><ab-custom-query dialog-key=\"zcgl_zcfl\" v-model=\"data.zcgl_zcxx\" :value-mapping=\"{bbhid:\'bbhid\',name:\'typeName\'}\" :immediate=\"false\" :param=\"{id_$VEQ:data.zcgl_zcxx.typeId || \'0\'}\"></ab-custom-query><ab-custom-query dialog-key=\"zcgl_cssx\" v-model=\"data.zcgl_zcxx.zcgl_type_relList\" :value-mapping=\"{id:\'paramId\',name:\'name\',isItMandatory:\'isItMandatory\'}\" :immediate=\"false\" :param=\"{cateId$VEQ:data.zcgl_zcxx.typeId}\" required-params=\"cateId$VEQ\"></ab-custom-query>\n</abTablePlugins>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	console.log(\"脚本将会混入自定义表单组件中...\");\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){  \n			// 执行业务校验，return false则终止提交 \n			return true;  \n		}\n	}\n }', 'design', '2023-10-26 15:59:38', '1602918114232172634', '1602918114232172544', '2023-11-22 15:00:32', '1602918114232172634', 0);
INSERT INTO `biz_form` VALUES ('1809123586590507008', 'pc', 'zcgl_zcjd_pc', '资产检定', 'zcgl', 'zcgl_zcjd', 'elementFlowDesign', 'zcgl_zcjd', '资产检定', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\" />\n<ab-form-group>\n	<ab-form-item class=\"is-required\" :span=\"24\" label=\"检定项目\" :permission=\"permission.zcgl_zcjd.zcgl_zcjd.name\">\n		<ab-input v-model=\"data.zcgl_zcjd.name\" placeholder=\"请输入检定项目\" :permission=\"permission.zcgl_zcjd.zcgl_zcjd.name\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产检定-检定项目\"></ab-input>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"24\" label=\"内容\" :permission=\"permission.zcgl_zcjd.zcgl_zcjd.content\">\n		<ab-input v-model=\"data.zcgl_zcjd.content\" placeholder=\"请输入内容\" :permission=\"permission.zcgl_zcjd.zcgl_zcjd.content\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产检定-内容\" type=\"textarea\" rows=\"2\"></ab-input>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"24\" label=\"编号\" :permission=\"permission.zcgl_zcjd.zcgl_zcjd.code\">\n		<ab-serial-no v-model=\"data.zcgl_zcjd.code\" placeholder=\"请输入编号\" :permission=\"permission.zcgl_zcjd.zcgl_zcjd.code\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产检定-编号\" serial-no-code=\"zcgl_zcjd\"></ab-serial-no>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"24\" label=\"检定范围\" :permission=\"permission.zcgl_zcjd.zcgl_zcjd.verificationscope\">\n		<ab-data-selector v-model=\"data.zcgl_zcjd.verificationscope\" placeholder=\"请输入检定范围\" :permission=\"permission.zcgl_zcjd.zcgl_zcjd.verificationscope\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产检定-检定范围\" dialog-key=\"zcgl_zcsyd\" label-field=\"name\" value-field=\"id\" select-type=\"custom\" param=\"id_\" icon=\"org\" search-desc=\"选择范围\" :dialog-setting=\"{ multiple: 1}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"24\" label=\"检定资产\" 