/th>\n							<th v-ab-permission=\"permission.zcgl_zcxx.zcgl_type_rel.val\" ><ab-required :permission=\"permission.zcgl_zcxx.zcgl_type_rel.val\"></ab-required>属性值</th>\n							<th>操作</th>\n						</tr>\n					</thead>\n					<tbody>\n						<ab-sub-tr-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.zcgl_zcxx.zcgl_type_rel\" :table-permission=\"tablePermission\" v-for=\"(zcgl_type_rel,index) in data.zcgl_zcxx.zcgl_type_relList\" :key=\"zcgl_type_rel.$$abHashCode\">\n							<td v-ab-permission=\"permission.zcgl_zcxx.zcgl_type_rel.name\">\n								<ab-input v-model=\"zcgl_type_rel.name\" placeholder=\"请输入属性名称\" :permission=\"scopePermission.name\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'资产分类属性关联-属性名称【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n							</td>\n							<td v-ab-permission=\"permission.zcgl_zcxx.zcgl_type_rel.val\">\n								<ab-input v-model=\"zcgl_type_rel.val\" placeholder=\"请输入属性值\" :permission=\"scopePermission.val\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'资产分类属性关联-属性值【第\'+(index+1)+\'条】\'\"></ab-input>\n							</td>\n							<td>\n								<ab-button-group>\n								</ab-button-group>\n								<abTablePlugins>\n									<ab-calculate v-model=\"data.zcgl_zcxx.zcgl_zccw.amount\" :script=\"abGetNumber(data.zcgl_zcxx.zcgl_zccw.price)*abGetNumber(data.zcgl_zcxx.zcgl_zccw.counts)\" desc=\"金额\" :decimals=\"2\"></ab-calculate>\n								</abTablePlugins>\n							</td>\n						</ab-sub-tr-scope>\n					</tbody>\n				</table>\n			</ab-card>\n		</ab-form-group>\n	</ab-card>\n	<ab-card style=\"margin-bottom: 15px;width: 100%;\" shadow=\"hover\">\n		<template #header>\n			<span class=\"title\">使用信息</span>\n		</template>\n		<ab-form-group>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"使用状态\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useStatus\">\n				<ab-tree-select v-model=\"data.zcgl_zcxx.useStatus\" placeholder=\"请输入使用状态\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useStatus\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-使用状态\" dic-code=\"zcgl_syzk\" :multiple=\"false\"></ab-tree-select>\n			</ab-form-item>\n			<ab-form-item  v-if=\"data.zcgl_zcxx.useStatus==\'syzk_zy\'\"  class=\"is-required\" :span=\"12\" label=\"使用时间\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useTime\">\n				<ab-date v-model=\"data.zcgl_zcxx.useTime\" placeholder=\"请输入使用时间\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useTime\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产信息-使用时间\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n			</ab-form-item>\n			<ab-form-item  v-if=\"data.zcgl_zcxx.useStatus==\'syzk_zy\'\"  class=\"is-required\" :span=\"12\" label=\"使用人\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useId\">\n				<ab-data-selector v-model=\"data.zcgl_zcxx.useId\" placeholder=\"请输入使用人\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useId\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-使用人\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"user\" param=\"userId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n			</ab-form-item>\n			<ab-form-item  v-if=\"data.zcgl_zcxx.useStatus==\'syzk_zy\'\"  class=\"is-required\" :span=\"12\" label=\"使用部门\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useDepId\">\n				<ab-data-selector v-model=\"data.zcgl_zcxx.useDepId\" placeholder=\"请输入使用部门\" :permission=\"permission.zcgl_zcxx.zcgl_zcxx.useDepId\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产信息-使用部门\" dialog-key=\"orgSelector\" label-field=\"name\" value-field=\"id\" select-type=\"org\" param=\"groupId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n			</ab-form-item>\n		</ab-form-group>\n	</ab-card>\n	<ab-card style=\"margin-bottom: 15px;width: 100%;\" shadow=\"hover\">\n		<template #header>\n			<span class=\"title\">资产金额</span>\n		</template>\n		<ab-form-group>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"单价\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.price\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.price\" placeholder=\"请输入单价\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.price\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-单价\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"购入数量\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.counts\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.counts\" placeholder=\"请输入购入数量\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.counts\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-购入数量\"></ab-input>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"金额（元）\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.amount\">\n				<ab-input v-model=\"data.zcgl_zcxx.zcgl_zccw.amount\" placeholder=\"请输入金额（元）\" :permission=\"permission.zcgl_zcxx.zcgl_zccw.amount\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"资产管理_资产财务-金额（元）\" :disabled=\"true\"></ab-input>\n			</ab-form-item>\n		</ab-form-group>\n	</ab-card>\n</ab-form-group>\n<abTablePlugins>\n	<ab-calculate v-model=\"data.zcgl_zcxx.zcgl_zccw.amount\" :script=\"abGetNumber(data.zcgl_zcxx.zcgl_zccw.price)*abGetNumber(data.zcgl_zcxx.zcgl_zccw.counts)\" desc=\"计算总金额\" :decimals=\"2\"></ab-calculate><ab-calculate v-model=\"data.zcgl_zcxx.zcgl_zccw.noneFiscalAllotment\" :script=\"abGetNumber(data.zcgl_zcxx.zcgl_zccw.amount)-abGetNumber(data.zcgl_zcxx.zcgl_zccw.fiscalAllotment)\" desc=\"赋值非拨款\" :decimals=\"2\"></ab-calculate><ab-custom-query dialog-key=\"zcgl_zcfl\" v-model=\"data.zcgl_zcxx\" :value-mapping=\"{bbhid:\'bbhid\',name:\'typeName\'}\" :immediate=\"false\" :param=\"{id_$VEQ:data.zcgl_zcxx.typeId || \'0\'}\"></ab-custom-query><ab-custom-query dialog-key=\"zcgl_cssx\" v-model=\"data.zcgl_zcxx.zcgl_type_relList\" :value-mapping=\"{id:\'paramId\',name:\'name\',isItMandatory:\'isItMandatory\'}\" :immediate=\"false\" :param=\"{cateId$VEQ:data.zcgl_zcxx.typeId}\" required-params=\"cateId$VEQ\"></ab-custom-query>\n</abTablePlugins>', '  window.custFormComponentMixin = {\n    data: function () {\n      return {\n        zjz: 0,\n        jz: 0,\n        paramList: [],\n        isRzRequired: false,\n        fczRequired: false,\n        czRequired: false,\n        asset_opt_info: {\n          status: \'\',\n          userName: \'\',\n          userId: \'\',\n          userDep: \'\',\n          userDepId: \'\',\n        },\n        assetBaseInfoBo: {},\n      }\n    },\n    created: function () {\n      if (this.$route.query.assetId) {\n        this.data.assetId = this.$route.query.assetId\n        this.queryAssetInfo(this.$route.query.assetId)\n      }\n    },\n    watch: {\n      \'data.assetFinancialInfoBo.entryStatus\': function (val) {\n        if (val == \'rzxs_yrz\') {\n          this.data.isRzRequired = true\n          return\n        }\n        this.data.isRzRequired = false\n      },\n      \'data.assetFinancialInfoBo.fundsSrc\': function (val) {\n        if (val == \'zjly_czxzj\') {\n          this.data.fczRequired = false\n          this.data.czRequired = true\n        } else if (val == \'zjly_fczzj\') {\n          this.data.czRequired = false\n          this.data.fczRequired = true\n        } else {\n          this.data.fczRequired = true\n          this.data.czRequired = true\n        }\n      },\n    },\n    computed: {},\n    methods: {\n      getMonthRange(data1, data2) {\n        if (!!data1 && !!data2) {\n          return Math.abs(\n            data1.getFullYear() * 12 +\n              data1.getMonth() +\n              1 -\n              (data2.getFullYear() * 12 + data2.getMonth() + 1)\n          )\n        } else {\n          return 0\n        }\n      },\n      bankersRounding(num, decimalPlaces) {\n        const d = decimalPlaces || 0\n        const m = Math.pow(10, d)\n        const n = +(d ? num * m : num).toFixed(8) // Avoid rounding errors\n        const i = Math.floor(n),\n          f = n - i\n        const e = 1e-8 // Allow for rounding errors in f\n        const r =\n          f > 0.5 - e && f < 0.5 + e ? (i % 2 == 0 ? i : i + 1) : Math.round(n)\n        return d ? r / m : r\n      },\n      celZj() {\n        // 如果折旧月份为 0，不折旧\n        // 如果折旧值 >= 原值， 完成折旧\n        // 其它状态为提折旧\n        // 月折旧值 = 原值 / 月份\n        // 净值 = 原值 - 累计折旧值\n        // 计算折旧值、净值\n        const that = this\n        if (that.assetBaseInfoBo.depreciable) {\n          // 不四舍五入\n          // const yzjz = Math.floor(that.data.assetFinancialInfoBo.amount / that.assetBaseInfoBo.depreciable * 100) / 100;\n          const yzjz = that.bankersRounding(\n            that.data.assetFinancialInfoBo.amount /\n              that.assetBaseInfoBo.depreciable,\n            2\n          )\n          const now = new Date()\n          const getDate = new Date(that.assetBaseInfoBo.getDate)\n          const monthCount = that.getMonthRange(now, getDate)\n          // 月份数超过折旧期限\n          if (monthCount < that.assetBaseInfoBo.depreciable) {\n            that.zjz = yzjz * monthCount\n            that.jz = that.bankersRounding(\n              that.data.assetFinancialInfoBo.amount - that.zjz,\n              2\n            )\n            that.data.assetFinancialInfoBo.depreciationDtatus = \'zjzt_tzj\'\n          } else {\n            that.zjz = that.data.assetFinancialInfoBo.amount\n            that.data.assetFinancialInfoBo.depreciationDtatus = \'zjzt_ywczj\'\n          }\n        } else {\n          that.data.assetFinancialInfoBo.depreciationDtatus = \'zjzt_btzj\'\n        }\n      },\n      queryAssetInfo: function (id) {\n        const that = this\n        const url = `/form/formDataService/getData/addAssetBaseInfoFormPc/${id}`\n        this.abHttpUtil\n          .get(url, {})\n          .then((result) => {\n            if (result.isOk) {\n              console.log(\n                \'queryAssetInfo ===> \',\n                result.data.data.assetBaseInfoBo\n              )\n              that.assetBaseInfoBo = result.data.data.assetBaseInfoBo\n              that.data.assetFinancialInfoBo =\n                result.data.data.assetBaseInfoBo.asset_financial_info\n              that.handleSelectType(that.assetBaseInfoBo)\n              that.paramList = that.assetBaseInfoBo.asset_param_valueList\n              that.queryUseInfo(that.assetBaseInfoBo.optId)\n              that.celZj()\n            }\n            this.$forceUpdate()\n          })\n          .catch((e) => console.log(\'error ===> \', e))\n      },\n      queryUseInfo: function (optId) {\n        const url = \'/form/formCustSql/view/list_gdzcgl-zcsyxx\'\n        const queryData = [\n          {\n            name: \'id\',\n            con: \'=\',\n            val: optId,\n          },\n        ]\n        const params = {\n          curPage: 1,\n          pageSize: 99,\n          params: JSON.stringify({ queryData }),\n        }\n        this.abHttpUtil\n          .post(url, params)\n          .then((result) => {\n            if (result.isOk) {\n              if (result.data.list?.length) {\n                this.asset_opt_info = result.data.list[0]\n              }\n            }\n            this.$forceUpdate()\n          })\n          .catch((e) => console.log(\'error ===> \', e))\n      },\n      handleSelectType(val) {\n        const { typeId } = val\n        const reqUrl = \'/form/formCustSql/view/list_gdzcgl-hqzctzzdxx\'\n        const queryData = [\n          {\n            name: \'cateId\',\n            con: \'like\',\n            val: typeId,\n          },\n        ]\n        const params = {\n          curPage: 1,\n          pageSize: 99,\n          params: JSON.stringify({ queryData }),\n        }\n        this.abHttpUtil.post(reqUrl, params).then((result) => {\n          if (result.isOk) {\n            if (result.data.list?.length) {\n              this.assetBaseInfoBo.asset_param_valueList = result.data.list.map(\n                (item) => {\n                  if (this.data.assetId && this.paramList.length) {\n                    let obj = {}\n                    this.paramList.forEach((cItem) => {\n                      if (item.paramId == cItem.paramId) {\n                        obj = {\n                          paramDesc: item.paramDesc,\n                          ...cItem,\n                        }\n                      }\n                    })\n                    item = obj\n                  } else {\n                    item.cateId = typeId\n                  }\n                  return item\n                }\n              )\n              return\n            }\n            this.$forceUpdate()\n          }\n        })\n      },\n      custValid: function () {\n        if(this.data.zcgl_zcxx.zcgl_type_relList && this.data.zcgl_zcxx.zcgl_type_relList.length>0){\n          debugger\n              for (let index in this.data.zcgl_zcxx.zcgl_type_relList) {\n                let item = this.data.zcgl_zcxx.zcgl_type_relList[index]\n                if(item.isItMandatory&& item.isItMandatory==1 && !item.val){\n                    this.abMessage({\n                      message: \'资产属性【\'+ item.name +\'】为必填属性！\',\n                      type: \'warning\'\n                    })\n                   return false;\n                }\n            }\n        }\n      \n        \n        // 执行业务校验，return false则终止提交\n        return true\n      },\n    },\n  }', 'change', '2023-07-13 18:03:45', '1602918114232172634', '1602918114232172544', '2023-11-22 15:00:33', '1602918114232172634', 0);
INSERT INTO `biz_form` VALUES ('1809123589065146368', 'pc', 'zcgl_zcwx_pc', '资产维修', 'zcgl', 'zcgl_zcwx', 'elementFlowDesign', 'zcgl_zcwx', '资产维修', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\" />\n<ab-form-group>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"申请部门\" :permission=\"permission.zcgl_zcwx.zcgl_zcwx.applicationDepartment\">\n		<ab-data-selector v-model=\"data.zcgl_zcwx.applicationDepartment\" placeholder=\"请输入申请部门\" :permission=\"permission.zcgl_zcwx.zcgl_zcwx.applicationDepartment\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产维修-申请部门\" dialog-key=\"orgSelector\" label-field=\"name\" value-field=\"id\" select-type=\"org\" param=\"groupId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"申请人\" :permission=\"permission.zcgl_zcwx.zcgl_zcwx.applicant\">\n		<ab-data-selector v-model=\"data.zcgl_zcwx.applicant\" placeholder=\"请输入申请人\" :permission=\"permission.zcgl_zcwx.zcgl_zcwx.applicant\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产维修-申请人\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"user\" param=\"userId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"紧急程度\" :permission=\"permission.zcgl_zcwx.zcgl_zcwx.level\">\n		<ab-radio-group v-model=\"data.zcgl_zcwx.level\" placeholder=\"请输入紧急程度\" :permission=\"permission.zcgl_zcwx.zcgl_zcwx.level\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产维修-紧急程度\" dic-code=\"zcgl_jjcd\"></ab-radio-group>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"申请时间\" :permission=\"permission.zcgl_zcwx.zcgl_zcwx.applicationTime\">\n		<ab-date v-model=\"data.zcgl_zcwx.applicationTime\" placeholder=\"请输入申请时间\" :permission=\"permission.zcgl_zcwx.zcgl_zcwx.applicationTime\" :rules=\"[{\'mes