rmission=\"permission.zcgl_cgxx.zcgl_cgxx.qzsmj\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_采购信息-签字\" column-name=\"qzsmj\" :only-write=\"false\"></ab-signature>\n	</ab-form-item>\n	<ab-card style=\"margin-bottom: 15px;width: 100%\" shadow=\"hover\" body-style=\"overflow:auto\">\n		<template #header>\n			<span class=\"title\">采购信息</span>\n			<ab-sub-load v-model=\"data.zcgl_cgxx\" table-path=\"zcgl_cgsbList\" bo-code=\"zcgl_cgxx\" :permission-type=\"permissionType\" :permission-value=\"permissionValue\" :permission=\"tablePermission.zcgl_cgxx.zcgl_cgsb\" fk=\"id\"></ab-sub-load>\n			<ab-sub-add class=\"el-button el-button--primary\" v-model=\"data.zcgl_cgxx.zcgl_cgsbList\" :init-data=\"initData.zcgl_cgxx.zcgl_cgsb\" :permission=\"tablePermission.zcgl_cgxx.zcgl_cgsb\" :init-first-row=\"false\">添加</ab-sub-add>\n		</template>\n		<table class=\"ab-table\">\n			<thead>\n				<tr>\n					<th v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.name\" ><ab-required></ab-required>资产名称</th>\n					<th v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.specification\" ><ab-required></ab-required>规格型号</th>\n					<th v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.contractNo\" ><ab-required></ab-required>合同编号</th>\n					<th v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.unit\" ><ab-required></ab-required>单位</th>\n					<th v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.num\" ><ab-required></ab-required>数量</th>\n					<th v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.price\" ><ab-required></ab-required>预算单价</th>\n					<th v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.amount\" ><ab-required :permission=\"permission.zcgl_cgxx.zcgl_cgsb.amount\"></ab-required>金额</th>\n					<th>操作</th>\n				</tr>\n			</thead>\n			<tbody>\n				<ab-sub-tr-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.zcgl_cgxx.zcgl_cgsb\" :table-permission=\"tablePermission\" v-for=\"(zcgl_cgsb,index) in data.zcgl_cgxx.zcgl_cgsbList\" :key=\"zcgl_cgsb.$$abHashCode\">\n					<td v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.name\">\n						<ab-input v-model=\"zcgl_cgsb.name\" placeholder=\"请输入资产名称\" :permission=\"scopePermission.name\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" :desc=\"\'资产管理_采购申报-资产名称【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.specification\">\n						<ab-input v-model=\"zcgl_cgsb.specification\" placeholder=\"请输入规格型号\" :permission=\"scopePermission.specification\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" :desc=\"\'资产管理_采购申报-规格型号【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.contractNo\">\n						<ab-input v-model=\"zcgl_cgsb.contractNo\" placeholder=\"请输入合同编号\" :permission=\"scopePermission.contractNo\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" :desc=\"\'资产管理_采购申报-合同编号【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.unit\">\n						<ab-tree-select v-model=\"zcgl_cgsb.unit\" placeholder=\"请输入单位\" :permission=\"scopePermission.unit\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" :desc=\"\'资产管理_采购申报-单位【第\'+(index+1)+\'条】\'\" dic-code=\"zcgl_jldw\" :multiple=\"false\"></ab-tree-select>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.num\">\n						<ab-input v-model=\"zcgl_cgsb.num\" placeholder=\"请输入数量\" :permission=\"scopePermission.num\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" :desc=\"\'资产管理_采购申报-数量【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.price\">\n						<ab-input v-model=\"zcgl_cgsb.price\" placeholder=\"请输入预算单价\" :permission=\"scopePermission.price\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" :desc=\"\'资产管理_采购申报-预算单价【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_cgxx.zcgl_cgsb.amount\">\n						<ab-input v-model=\"zcgl_cgsb.amount\" placeholder=\"请输入金额\" :permission=\"scopePermission.amount\" :rules=\"[]\" :desc=\"\'资产管理_采购申报-金额【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n					</td>\n					<td>\n						<ab-button-group>\n							<ab-sub-del v-model=\"data.zcgl_cgxx.zcgl_cgsbList\" :index=\"index\" :permission=\"scopeTablePermission.zcgl_cgxx.zcgl_cgsb\">移除</ab-sub-del>\n						</ab-button-group>\n						<abTablePlugins>\n							<ab-calculate v-model=\"zcgl_cgsb.amount\" :script=\"abGetNumber(zcgl_cgsb.num)*abGetNumber(zcgl_cgsb.price)\" desc=\"计算总金额\" :decimals=\"2\"></ab-calculate>\n						</abTablePlugins>\n					</td>\n				</ab-sub-tr-scope>\n			</tbody>\n		</table>\n	</ab-card>\n</ab-form-group>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	console.log(\"脚本将会混入自定义表单组件中...\");\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){\n			// 执行业务校验，return false则终止提交 \n      if(this.data.zcgl_cgxx.zcgl_cgsbList && this.data.zcgl_cgxx.zcgl_cgsbList.length > 0 ){\n			return true;  \n     } else{\n        this.abMessage({\n          message: \'请添加要采购的资产\',\n            type: \'warning\'\n          })\n        return false;\n     }\n    \n		}\n	}\n}', 'design', '2023-07-21 10:30:47', '1602918114232172634', '1602918114232172544', '2023-11-22 15:00:33', '1602918114232172634', 0);
