INSERT INTO `biz_form` VALUES ('1809123591854358528', 'pc', 'zcgl_zcly_pc', '资产领用', 'zcgl', 'zcgl_zcly', 'elementFlowDesign', 'zcgl_zclz', '资产流转', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\" />\n<ab-form-group>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"使用人\" :permission=\"permission.zcgl_zclz.zcgl_zclz.curUser\">\n		<ab-data-selector v-model=\"data.zcgl_zclz.curUser\" placeholder=\"请输入使用人\" :permission=\"permission.zcgl_zclz.zcgl_zclz.curUser\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产流转-使用人\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"user\" param=\"userId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"使用部门\" :permission=\"permission.zcgl_zclz.zcgl_zclz.curDep\">\n		<ab-data-selector v-model=\"data.zcgl_zclz.curDep\" placeholder=\"请输入使用部门\" :permission=\"permission.zcgl_zclz.zcgl_zclz.curDep\" :rules=\"[]\" desc=\"资产管理_资产流转-使用部门\" dialog-key=\"orgSelector\" label-field=\"name\" value-field=\"id\" select-type=\"org\" param=\"groupId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"申请类型\" :permission=\"permission.zcgl_zclz.zcgl_zclz.transferType\">\n		<ab-radio-group v-model=\"data.zcgl_zclz.transferType\" placeholder=\"请输入转移类型\" :permission=\"permission.zcgl_zclz.zcgl_zclz.transferType\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产流转-申请类型\" :options=\"[{\'key\':\'1\',\'text\':\'领用\'},{\'key\':\'2\',\'text\':\'借用\'}]\"></ab-radio-group>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"编号\" :permission=\"permission.zcgl_zclz.zcgl_zclz.code\">\n		<ab-serial-no v-model=\"data.zcgl_zclz.code\" placeholder=\"请输入编号\" :permission=\"permission.zcgl_zclz.zcgl_zclz.code\" :rules=\"[]\" desc=\"资产管理_资产流转-编号\" :disabled=\"true\" serial-no-code=\"zcgl_zcly\"></ab-serial-no>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"领用时间\" :permission=\"permission.zcgl_zclz.zcgl_zclz.optTime\">\n		<ab-date v-model=\"data.zcgl_zclz.optTime\" placeholder=\"请输入操作时间\" :permission=\"permission.zcgl_zclz.zcgl_zclz.optTime\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产流转-领用时间\" type=\"date\" format=\"YYYY-MM-DD\" min=\"${currentDateTime}\"></ab-date>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"预计归还日期\" v-if=\"data.zcgl_zclz.transferType==2\" :permission=\"permission.zcgl_zclz.zcgl_zclz.expectReturned\">\n		<ab-date v-model=\"data.zcgl_zclz.expectReturned\" placeholder=\"请输入预计归还日期\" :permission=\"permission.zcgl_zclz.zcgl_zclz.expectReturned\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_资产流转-预计归还日期\" type=\"date\" format=\"YYYY-MM-DD\" min=\"${currentDateTime}\"></ab-date>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"说明\" :permission=\"permission.zcgl_zclz.zcgl_zclz.description\">\n		<ab-input v-model=\"data.zcgl_zclz.description\" placeholder=\"请输入说明\" :permission=\"permission.zcgl_zclz.zcgl_zclz.description\" :rules=\"[]\" desc=\"资产管理_资产流转-说明\" type=\"textarea\" rows=\"2\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"附件\" :permission=\"permission.zcgl_zclz.zcgl_zclz.atta\">\n		<ab-upload v-model=\"data.zcgl_zclz.atta\" :permission=\"permission.zcgl_zclz.zcgl_zclz.atta\" :rules=\"[]\" desc=\"资产管理_资产流转-附件\" list-type=\"text\" dic-code=\"ywfj\"></ab-upload>\n	</ab-form-item>\n	<ab-card style=\"margin-bottom: 15px;width: 100%\" shadow=\"hover\" body-style=\"overflow:auto\">\n		<template #header>\n			<span class=\"title\">领用资产</span>\n			<ab-sub-load v-model=\"data.zcgl_zclz\" table-path=\"zcgl_lzglzcList\" bo-code=\"zcgl_zclz\" :permission-type=\"permissionType\" :permission-value=\"permissionValue\" :permission=\"tablePermission.zcgl_zclz.zcgl_lzglzc\" fk=\"id\"></ab-sub-load>\n			<ab-cust-dialog v-model=\"data.zcgl_zclz.zcgl_lzglzcList\" style=\"margin-left:5px;\" size=\"small\" icon=\"Search\" type=\"primary\" v-if=\"[\'b\',\'w\'].includes(tablePermission.zcgl_zclz.zcgl_lzglzc)\" dialog-key=\"zcgl_xzzcxz\" :value-mapping=\"{id:\'assetId\',specification:\'specificationAndModel\',code:\'assetNumber\',name:\'assetName\',typeName:\'assetClassification\',unit:\'unit\'}\" :dialog-setting=\"{ multiple: 1}\" :show-detail=\"false\">\n				选择资产\n			</ab-cust-dialog>\n		</template>\n		<table class=\"ab-table\">\n			<thead>\n				<tr>\n					<th v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetName\" ><ab-required :permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetName\"></ab-required>资产名称</th>\n					<th v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetNumber\" ><ab-required :permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetNumber\"></ab-required>资产编号</th>\n					<th v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetClassification\" ><ab-required :permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetClassification\"></ab-required>资产分类</th>\n					<th v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.specificationAndModel\" ><ab-required :permission=\"permission.zcgl_zclz.zcgl_lzglzc.specificationAndModel\"></ab-required>规格型号</th>\n					<th v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.unit\" ><ab-required :permission=\"permission.zcgl_zclz.zcgl_lzglzc.unit\"></ab-required>单位	</th>\n					<th>操作</th>\n				</tr>\n			</thead>\n			<tbody>\n				<ab-sub-tr-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.zcgl_zclz.zcgl_lzglzc\" :table-permission=\"tablePermission\" v-for=\"(zcgl_lzglzc,index) in data.zcgl_zclz.zcgl_lzglzcList\" :key=\"zcgl_lzglzc.$$abHashCode\">\n					<td v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetName\">\n						<ab-input v-model=\"zcgl_lzglzc.assetName\" placeholder=\"请输入资产名称\" :permission=\"scopePermission.assetName\" :rules=\"[]\" :desc=\"\'资产管理_流转关联资产-资产名称【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetNumber\">\n						<ab-input v-model=\"zcgl_lzglzc.assetNumber\" placeholder=\"请输入资产编号\" :permission=\"scopePermission.assetNumber\" :rules=\"[]\" :desc=\"\'资产管理_流转关联资产-资产编号【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.assetClassification\">\n						<ab-input v-model=\"zcgl_lzglzc.assetClassification\" placeholder=\"请输入资产分类\" :permission=\"scopePermission.assetClassification\" :rules=\"[]\" :desc=\"\'资产管理_流转关联资产-资产分类【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.specificationAndModel\">\n						<ab-input v-model=\"zcgl_lzglzc.specificationAndModel\" placeholder=\"请输入规格型号\" :permission=\"scopePermission.specificationAndModel\" :rules=\"[]\" :desc=\"\'资产管理_流转关联资产-规格型号【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_zclz.zcgl_lzglzc.unit\">\n						<ab-tree-select v-model=\"zcgl_lzglzc.unit\" placeholder=\"请输入单位	\" :permission=\"scopePermission.unit\" :rules=\"[]\" :desc=\"\'资产管理_流转关联资产-单位	【第\'+(index+1)+\'条】\'\" :disabled=\"true\" dic-code=\"zcgl_jldw\" :multiple=\"false\"></ab-tree-select>\n					</td>\n					<td>\n						<ab-button-group v-if=\"!data.zcgl_zclz.zcgl_lzglzcList[index].id\">\n							<ab-sub-del v-model=\"data.zcgl_zclz.zcgl_lzglzcList\" :index=\"index\" :permission=\"scopeTablePermission.zcgl_zclz.zcgl_lzglzc\">移除</ab-sub-del>\n						</ab-button-group>\n					</td>\n				</ab-sub-tr-scope>\n			</tbody>\n		</table>\n	</ab-card>\n</ab-form-group>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	console.log(\"脚本将会混入自定义表单组件中...\");\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){  \n	if(!this.data.zcgl_zclz.zcgl_lzglzcList || this.data.zcgl_zclz.zcgl_lzglzcList.length==0){\n        this.abMessage({\n          message: \'请选择领用资产\',\n            type: \'warning\'\n          })\n        return false;\n      }\n			return true;  \n		}\n	}\n }', 'change', '2023-07-21 17:54:41', '1602918114232172634', '1602918114232172544', '2023-11-22 15:00:33', '1602918114232172634', 0);
