INSERT INTO `biz_form` VALUES ('1809123596140937216', 'pc', 'zcgl_ckxx_pc', '退库信息', 'zcgl', 'zcgl_ckxx', 'elementFlowDesign', 'zcgl_ckxx', '出库信息', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\" />\n<ab-form-group>\n	<ab-card style=\"margin-bottom: 15px;width: 100%;\" shadow=\"hover\">\n		<template #header>\n			<span class=\"title\">退库信息</span>\n		</template>\n		<ab-form-group>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"退库处理人\" :permission=\"permission.zcgl_ckxx.zcgl_ckxx.userId\">\n				<ab-data-selector v-model=\"data.zcgl_ckxx.userId\" placeholder=\"请输入出库处理人\" :permission=\"permission.zcgl_ckxx.zcgl_ckxx.userId\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_退库信息-退库处理人\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"user\" param=\"userId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n			</ab-form-item>\n			<ab-form-item :span=\"12\" label=\"退库编号\" :permission=\"permission.zcgl_ckxx.zcgl_ckxx.ckNo\">\n				<ab-serial-no v-model=\"data.zcgl_ckxx.ckNo\" placeholder=\"请输入出库单号\" :permission=\"permission.zcgl_ckxx.zcgl_ckxx.ckNo\" :rules=\"[]\" desc=\"资产管理_退库信息-退库编号\" :disabled=\"true\" serial-no-code=\"zcgl_ckgl\"></ab-serial-no>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"退库时间\" :permission=\"permission.zcgl_ckxx.zcgl_ckxx.ckTime\">\n				<ab-date v-model=\"data.zcgl_ckxx.ckTime\" placeholder=\"请输入出库时间\" :permission=\"permission.zcgl_ckxx.zcgl_ckxx.ckTime\" :rules=\"[{\'message\':\'必填\',\'required\':true}]\" desc=\"资产管理_退库信息-退库时间\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n			</ab-form-item>\n			<ab-form-item class=\"is-required\" :span=\"12\" label=\"退库存放地\" :permission=\"permission.zcgl_ckxx.zcgl_ckxx.storeArea\">\n				<ab-data-selector v-model=\"data.zcgl_ckxx.storeArea\" placeholder=\"请输入资产存放地\" :permission=\"permission.zcgl_ckxx.zcgl_ckxx.storeArea\" :rules=\"[{\'message\':\'必填\',\'required\':true