ceholder=\"请输入分类名称\" :permission=\"scopePermission.typeName\" :rules=\"[]\" :desc=\"\'资产管理_出库子表-资产分类【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_ckxx.zcgl_ckzb.specification\">\n						<ab-input v-model=\"zcgl_ckzb.specification\" placeholder=\"请输入规格型号\" :permission=\"scopePermission.specification\" :rules=\"[]\" :desc=\"\'资产管理_出库子表-规格型号【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.zcgl_ckxx.zcgl_ckzb.unit\">\n						<ab-tree-select v-model=\"zcgl_ckzb.unit\" placeholder=\"请输入计量单位\" :permission=\"scopePermission.unit\" :rules=\"[]\" :desc=\"\'资产管理_出库子表-计量单位【第\'+(index+1)+\'条】\'\" :disabled=\"true\" dic-code=\"zcgl_jldw\" :multiple=\"false\"></ab-tree-select>\n					</td>\n					<td>\n						<ab-button-group>\n							<ab-sub-del v-model=\"data.zcgl_ckxx.zcgl_ckzbList\" :index=\"index\" :permission=\"scopeTablePermission.zcgl_ckxx.zcgl_ckzb\">移除</ab-sub-del>\n						</ab-button-group>\n					</td>\n				</ab-sub-tr-scope>\n			</tbody>\n		</table>\n	</ab-card>\n</ab-form-group>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	console.log(\"脚本将会混入自定义表单组件中...\");\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){  \n	    if(!this.data.zcgl_ckxx.zcgl_ckzbList || this.data.zcgl_ckxx.zcgl_ckzbList.length==0){\n        this.abMessage({\n          message: \'请选择退库资产\',\n            type: \'warning\'\n          })\n        return false;\n      }\n  		return true;  \n		}\n	}\n }', 'change', '2023-07-18 11:50:31', '1602918114232172634', '1602918114232172544', '2023-11-22 15:00:34', '1602918114232172634', 0);
INSERT INTO `biz_form` VALUES ('1810507429063118848', 'pc', 'addingclues_V2_pc', '个人线索', 'crm', 'addingclues_V2', 'elementFlowDesign', 'newcustomers', '新增客户', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-divider content-position=\"left\">客户信息</ab-divider>\n	<ab-form-item class=\"is-required\" :span=\"8\" label=\"客户名称\" :permission=\"permission.newcustomers.customerInformation.customerName\">\n		<ab-custom-dialog v-model=\"data.newcustomers.customerName\" placeholder=\"请输入客户名称\" :permission=\"permission.newcustomers.customerInformation.customerName\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索-客户名称\" dialog-key=\"customersearch\" search-desc=\"查重\" :object-mapping=\"data.newcustomers\" :value-mapping=\"{customerName:\'customerName\'}\" :dialog-setting=\"{ multiple: 0}\" :param=\"{customer_name_$VLK:data.newcustomers.customerName}\" :mapping-init-data=\"initData.newcustomers.customerInformation\" :show-detail=\"false\"></ab-custom-dialog>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"线索阶段\" :permission=\"permission.newcustomers.customerInformation.customerstage\">\n		<ab-select v-model=\"data.newcustomers.customerstage\" placeholder=\"请输入客户阶段\" :permission=\"permission.newcustomers.customerInformation.customerstage\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索-线索阶段\" :options=\"[{\'key\':\'1\',\'text\':\'新增线索\'},{\'key\':\'2\',\'text\':\'领取线索\'},{\'key\':\'3\',\'text\':\'退回线索\'}]\"></ab-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"线索来源\" :permission=\"permission.newcustomers.customerInformation.customerSource\">\n		<ab-tree-select v-model=\"data.newcustomers.customerSource\" placeholder=\"请输入客户来源\" :permission=\"permission.newcustomers.customerInformation.customerSource\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索-线索来源\" dic-code=\"sourcesofclues\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"标签\" :permission=\"permission.newcustomers.customerInformation.label\">\n		<ab-tree-select v-model=\"data.newcustomers.label\" placeholder=\"请输入标签\" :permission=\"permission.newcustomers.customerInformation.label\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索-标签\" dic-code=\"label\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"所属行业\" :permission=\"permission.newcustomers.customerInformation.industry\">\n		<ab-tree-select v-model=\"data.newcustomers.industry\" placeholder=\"请输入所属行业\" :permission=\"permission.newcustomers.customerInformation.industry\" :rules=\"[{\'max\':255,\'message\':\'最多可输入255个字符\'}]\" desc=\"个人线索-所属行业\" dic-code=\"industry\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"线索池\" :permission=\"permission.newcustomers.customerInformation.cluePool\">\n		<ab-tree-select v-model=\"data.newcustomers.cluePool\" placeholder=\"请输入线索池\" :permission=\"permission.newcustomers.customerInformation.cluePool\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索-线索池\" dic-code=\"regionaldivision\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"线索详情\" :permission=\"permission.newcustomers.customerInformation.demand\">\n		<ab-input v-model=\"data.newcustomers.demand\" placeholder=\"请输入线索详情\" :permission=\"permission.newcustomers.customerInformation.demand\" :rules=\"[]\" desc=\"个人线索-线索详情\" type=\"textarea\" rows=\"3\"></ab-input>\n	</ab-form-item>\n	<ab-card style=\"margin-bottom: 15px;width: 100%\" shadow=\"hover\" body-style=\"overflow:auto\" v-ab-permission=\"tablePermission.newcustomers.contactInformation\">\n		<template #header>\n			<span class=\"title\">联系人信息</span>\n			<ab-sub-load v-model=\"data.newcustomers\" table-path=\"contactInformationList\" bo-code=\"newcustomers\" :permission-type=\"permissionType\" :permission-value=\"permissionValue\" :permission=\"tablePermission.newcustomers.contactInformation\" fk=\"id,id\"></ab-sub-load>\n			<ab-sub-add class=\"el-button el-button--primary\" v-model=\"data.newcustomers.contactInformationList\" :init-data=\"initData.newcustomers.contactInformation\" :permission=\"tablePermission.newcustomers.contactInformation\" :init-first-row=\"true\">添加</ab-sub-add>\n		</template>\n		<table class=\"ab-table\">\n			<thead>\n				<tr>\n					<th class=\"ab-table-sn\">序号</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.decisionMakerOrNot\" ><ab-required :permission=\"permission.newcustomers.contactInformation.decisionMakerOrNot\"></ab-required>是否决策人</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.contactName\" ><ab-required></ab-required>姓名</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.mobilePhoneNumber\" ><ab-required :permission=\"permission.newcustomers.contactInformation.mobilePhoneNumber\"></ab-required>手机号</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.post\" ><ab-required :permission=\"permission.newcustomers.contactInformation.post\"></ab-required>职务</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.wechatSignal\" ><ab-required :permission=\"permission.newcustomers.contactInformation.wechatSignal\"></ab-required>微信号</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.mailbox\" ><ab-required :permission=\"permission.newcustomers.contactInformation.mailbox\"></ab-required>邮箱</th>\n					<th>操作</th>\n				</tr>\n			</thead>\n			<tbody>\n				<ab-sub-tr-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.newcustomers.contactInformation\" :table-permission=\"tablePermission\" v-for=\"(contactInformation,index) in data.newcustomers.contactInformationList\" :key=\"contactInformation.$abHashCode\">\n					<td>{{index+1}}</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.decisionMakerOrNot\">\n						<ab-switch v-model=\"contactInformation.decisionMakerOrNot\" :permission=\"scopePermission.decisionMakerOrNot\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-是否决策人【第\'+(index+1)+\'条】\'\" active-text=\"是\" inactive-text=\"否\" active-value=\"1\" inactive-value=\"0\"></ab-switch>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.contactName\">\n						<ab-input v-model=\"contactInformation.contactName\" placeholder=\"请输入联系人姓名\" :permission=\"scopePermission.contactName\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-姓名【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.mobilePhoneNumber\">\n						<ab-input v-model=\"contactInformation.mobilePhoneNumber\" placeholder=\"请输入手机号\" :permission=\"scopePermission.mobilePhoneNumber\" :rules=\"[{\'pattern\':\'((\\\\d{11})|^((\\\\d{7,8})|(\\\\d{4}|\\\\d{3})-(\\\\d{7,8})|(\\\\d{4}|\\\\d{3})-(\\\\d{7,8})-(\\\\d{4}|\\\\d{3}|\\\\d{2}|\\\\d{1})|(\\\\d{7,8})-(\\\\d{4}|\\\\d{3}|\\\\d{2}|\\\\d{1}))$)\',\'message\':\'请输入正确的手机号码\'},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-手机号【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.post\">\n						<ab-input v-model=\"contactInformation.post\" placeholder=\"请输入职务\" :permission=\"scopePermission.post\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-职务【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.wechatSignal\">\n						<ab-input v-model=\"contactInformation.wechatSignal\" placeholder=\"请输入微信号\" :permission=\"scopePermission.wechatSignal\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-微信号【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.mailbox\">\n						<ab-input v-model=\"contactInformation.mailbox\" placeholder=\"请输入邮箱\" :permission=\"scopePermission.mailbox\" :rules=\"[{\'pattern\':\'^[a-zA-Z0-9_-]+@[a-zA-Z0-9_-]+(\\\\.[a-zA-Z0-9_-]+)+$\',\'message\':\'请输入合法的邮箱地址\'},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-邮箱【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td>\n						<ab-button-group>\n							<ab-sub-del v-model=\"data.newcustomers.contactInformationList\" :index=\"index\" :permission=\"scopeTablePermission.newcustomers.contactInformation\">移除</ab-sub-del>\n						</ab-button-group>\n					</td>\n				</ab-sub-tr-scope>\n			</tbody>\n		</table>\n	</ab-card>\n	<ab-form-item :span=\"12\" label=\"客户经理\" :permission=\"permission.newcustomers.customerInformation.responsibleperson\">\n		<ab-data-selector v-model=\"data.newcustomers.responsibleperson\" placeholder=\"请输入客户经理\" :permission=\"permission.newcustomers.customerInformation.responsibleperson\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索-客户经理\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"user\" param=\"userId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n</ab-form-group>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	const hasSubTable = this.data.newcustomers.contactInformationList && this.data.newcustomers.contactInformationList.length>0\n      if(this.data.lxr && !hasSubTable){\n        this.data.newcustomers.contactInformationList = [{contactName:this.data.lxr,mobilePhoneNumber:this.data.lxsj }]\n      }\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){  \n			// 执行业务校验，return false则终止提交 \n			return true;  \n		}\n	}\n }', 'design', '2023-11-16 17:39:50', '1602918114232172634', '1602918114232172544', '2024-01-21 20:00:25', '1602918114232172634', 0);
