INSERT INTO `biz_form` VALUES ('1810507436008886272', 'pc', 'productmaintenance_pc', '产品维护', 'crm', 'productmaintenance', 'elementFlowDesign', 'productmaintenance', '产品维护', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-form-item :span=\"24\" label=\"产品名称\" :permission=\"permission.productmaintenance.productmaintenance.productName\">\n		<ab-input v-model=\"data.productmaintenance.productName\" placeholder=\"请输入产品名称\" :permission=\"permission.productmaintenance.productmaintenance.productName\" :rules=\"[]\" desc=\"产品维护-产品名称\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"规格型号\" :permission=\"permission.productmaintenance.productmaintenance.specificationAndModel\">\n		<ab-input v-model=\"data.productmaintenance.specificationAndModel\" placeholder=\"请输入规格型号\" :permission=\"permission.productmaintenance.productmaintenance.specificationAndModel\" :rules=\"[]\" desc=\"产品维护-规格型号\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"单位\" :permission=\"permission.productmaintenance.productmaintenance.unit\">\n		<ab-tree-select v-model=\"data.productmaintenance.unit\" placeholder=\"请输入单位\" :permission=\"permission.productmaintenance.productmaintenance.unit\" :rules=\"[]\" desc=\"产品维护-单位\" dic-code=\"productunit\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"价格\" :permission=\"permission.productmaintenance.productmaintenance.price\">\n		<ab-input v-model=\"data.productmaintenance.price\" placeholder=\"请输入价格\" :permission=\"permission.productmaintenance.productmaintenance.price\" :rules=\"[]\" desc=\"产品维护-价格\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"数量\" :permission=\"permission.productmaintenance.productmaintenance.quantity\">\n		<ab-input v-model=\"data.productmaintenance.quantity\" placeholder=\"请输入数量\" :permission=\"permission.productmaintenance.productmaintenance.quantity\" :rules=\"[]\" desc=\"产品维护-数量\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"图片\" :permission=\"permission.productmaintenance.productmaintenance.picture\">\n		<ab-upload v-model=\"data.productmaintenance.picture\" :permission=\"permission.productmaintenance.productmaintenance.picture\" :rules=\"[]\" desc=\"产品维护-图片\" list-type=\"picture-card\" dic-code=\"ywfj\" :multiple=\"true\"></ab-upload>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"状态\" :permission=\"permission.productmaintenance.productmaintenance.state\">\n		<ab-tree-select v-model=\"data.productmaintenance.state\" placeholder=\"请输入状态\" :permission=\"permission.productmaintenance.productmaintenance.state\" :rules=\"[]\" desc=\"产品维护-状态\" dic-code=\"productstatus\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"详情\" :permission=\"permission.productmaintenance.productmaintenance.details\">\n		<ab-input v-model=\"data.productmaintenance.details\" placeholder=\"请输入详情\" :permission=\"permission.productmaintenance.productmaintenance.details\" :rules=\"[]\" desc=\"产品维护-详情\" type=\"textarea\" rows=\"2\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"添加人\" :permission=\"permission.productmaintenance.productmaintenance.addPeople\">\n		<ab-input v-model=\"data.productmaintenance.addPeople\" placeholder=\"请输入添加人\" :permission=\"permission.productmaintenance.productmaintenance.addPeople\" :rules=\"[]\" desc=\"产品维护-添加人\" :disabled=\"true\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"添加时间\" :permission=\"permission.productmaintenance.productmaintenance.addtime\">\n		<ab-date v-model=\"data.productmaintenance.addtime\" placeholder=\"请输入添加时间\" :permission=\"permission.productmaintenance.productmaintenance.addtime\" :rules=\"[]\" desc=\"产品维护-添加时间\" :disabled=\"true\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n	</ab-form-item>\n</ab-form-group>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	console.log(\"脚本将会混入自定义表单组件中...\");\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){  \n			// 执行业务校验，return false则终止提交 \n			return true;  \n		}\n	}\n }', 'design', '2023-08-07 10:37:49', '1602918114232172634', '1602918114232172544', '2023-12-29 17:42:56', '1602918114232172634', 0);
INSERT INTO `biz_form` VALUES ('1810507437388812288', 'pc', 'businessopportunity_pc', '商机', 'crm', 'businessopportunity', 'elementFlowDesign', 'businessopportunity', '商机', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-form-item :span=\"12\" label=\"客户名称\" :permission=\"permission.businessopportunity.businessOpportunity.customerName\">\n		<ab-data-selector v-model=\"data.businessopportunity.customerName\" placeholder=\"请输入客户id\" :permission=\"permission.businessopportunity.businessOpportunity.customerName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-客户名称\" dialog-key=\"selectingCustomers\" label-field=\"customerName\" value-field=\"id\" select-type=\"custom\" param=\"id_\" icon=\"customer\" :dialog-setting=\"{ multiple: 0}\" :show-detail=\"true\" detail-form-code=\"addCustomer_V2_pc\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"客户联系人\" :permission=\"permission.businessopportunity.businessOpportunity.customerContact\">\n		<ab-custom-dialog v-model=\"data.businessopportunity.customerContact\" placeholder=\"请输入客户联系人\" :permission=\"permission.businessopportunity.businessOpportunity.customerContact\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-客户联系人\" dialog-key=\"selectcontacts\" :object-mapping=\"data.businessopportunity\" :value-mapping=\"{contactName:\'customerContact\'}\" :dialog-setting=\"{ multiple: 0}\" :param=\"{enterprise_name_$VEQ:data.businessopportunity.customerName}\" :show-detail=\"false\"></ab-custom-dialog>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"商机名称\" :permission=\"permission.businessopportunity.businessOpportunity.opportunityName\">\n		<ab-input v-model=\"data.businessopportunity.opportunityName\" placeholder=\"请输入商机名称\" :permission=\"permission.businessopportunity.businessOpportunity.opportunityName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-商机名称\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"负责人\" :permission=\"permission.businessopportunity.businessOpportunity.responsiblePerson\">\n		<ab-data-selector v-model=\"data.businessopportunity.responsiblePerson\" placeholder=\"请输入负责人\" :permission=\"permission.businessopportunity.businessOpportunity.responsiblePerson\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-负责人\" :disabled=\"true\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"user\" param=\"userId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item :label-width=\"0\" :span=\"24\" label=\"商机进度\" :permission=\"permission.businessopportunity.businessOpportunity.schedule\">\n		<ab-steps v-model=\"data.businessopportunity.schedule\" :permission=\"permission.businessopportunity.businessOpportunity.schedule\" :rules=\"[{\'pattern\':\'^([0-9]|[0-9]\\\\d|100)$\',\'message\':\'请输入1-100数字\'},{\'max\':8,\'message\':\'最多可输入8个字符\'}]\" desc=\"商机-商机进度\" :param=\"[{\'value\':0,\'label\':\'需求发现\',\'default\':true},{\'value\':1,\'label\':\'需求确认\',\'default\':false},{\'value\':2,\'label\':\'方案报价\',\'default\':false},{\'value\':3,\'label\':\'商务谈判\',\'default\':false},{\'value\':4,\'label\':\'合同签订\',\'default\':false}]\"></ab-steps>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"商机状态\" :permission=\"permission.businessopportunity.businessOpportunity.salesPhase\">\n		<ab-radio-group v-model=\"data.businessopportunity.salesPhase\" placeholder=\"请输入销售阶段\" :permission=\"permission.businessopportunity.businessOpportunity.salesPhase\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-商机状态\" :options=\"[{\'key\':\'1\',\'text\':\'进行中\'},{\'key\':\'2\',\'text\':\'赢单\'},{\'key\':\'3\',\'text\':\'输单\'},{\'key\':\'4\',\'text\':\'无效\'}]\"></ab-radio-group>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"商机时间\" :permission=\"permission.businessopportunity.businessOpportunity.opportunitytime\">\n		<ab-date v-model=\"data.businessopportunity.opportunitytime\" placeholder=\"请输入商机时间\" :permission=\"permission.businessopportunity.businessOpportunity.opportunitytime\" :rules=\"[]\" desc=\"商机-商机时间\" :disabled=\"true\" type=\"date\" format=\"YYYY-MM-DD HH:mm\"></ab-date>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"备注\" :permission=\"permission.businessopportunity.businessOpportunity.remarks\">\n		<ab-input v-model=\"data.businessopportunity.remarks\" placeholder=\"请输入备注\" :permission=\"permission.businessopportunity.businessOpportunity.remarks\" :rules=\"[{\'max\':500,\'message\':\'最多可输入500个字符\'}]\" desc=\"商机-备注\" type=\"textarea\" rows=\"3\"></ab-input>\n	</ab-form-item>\n	<ab-card style=\"margin-bottom: 15px;width: 100%\" shadow=\"hover\" body-style=\"overflow:auto\" v-ab-permission=\"tablePermission.businessopportunity.productDetails\">\n		<template #header>\n			<span class=\"title\">产品明细</span>\n			<ab-sub-load v-model=\"data.businessopportunity\" table-path=\"productDetailsList\" bo-code=\"businessopportunity\" :permission-type=\"permissionType\" :permission-value=\"permissionValue\" :permission=\"tablePermission.businessopportunity.productDetails\" fk=\"customerName\"></ab-sub-load>\n			<ab-sub-add class=\"el-button el-button--primary\" v-model=\"data.businessopportunity.productDetailsList\" :init-data=\"initData.businessopportunity.productDetails\" :permission=\"tablePermission.businessopportunity.productDetails\" :init-first-row=\"true\">添加</ab-sub-add>\n		</template>\n		<table class=\"ab-table\">\n			<thead>\n				<tr>\n					<th class=\"ab-table-sn\">序号</th>\n					<th v-ab-permission=\"permission.businessopportunity.productDetails.productName\" ><ab-required :permission=\"permission.businessopportunity.productDetails.productName\"></ab-required>产品名称</th>\n					<th v-ab-permission=\"permission.businessopportunity.productDetails.specificationAndModel\" ><ab-required :permission=\"permission.businessopportunity.productDetails.specificationAndModel\"></ab-required>规格型号</th>\n					<th v-ab-permission=\"permission.businessopportunity.productDetails.unit\" ><ab-required :permission=\"permission.businessopportunity.productDetails.unit\"></ab-required>单位</th>\n					<th v-ab-permission=\"permission.businessopportunity.productDetails.price\" ><ab-required :permission=\"permission.businessopportunity.productDetails.price\"></ab-required>单价(元)</th>\n					<th v-ab-permission=\"permission.businessopportunity.productDetails.quantity\" ><ab-required :permission=\"permission.businessopportunity.productDetails.quantity\"></ab-required>数量</th>\n					<th v-ab-permission=\"permission.businessopportunity.productDetails.zkfs\" ><ab-required :permission=\"permission.businessopportunity.productDetails.zkfs\"></ab-required>折扣方式</th>\n					<th v-ab-permission=\"permission.businessopportunity.productDetails.discount\" ><ab-required></ab-required>折扣</th>\n					<th v-ab-permission=\"permission.businessopportunity.productDetails.subtotal\" ><ab-required :permission=\"permission.businessopportunity.productDetails.subtotal\"></ab-required>小计(元)</th>\n					<th>操作</th>\n				</tr>\n			</thead>\n			<tbody>\n				<ab-sub-tr-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.businessopportunity.productDetails\" :table-permission=\"tablePermission\" v-for=\"(productDetails,index) in data.businessopportunity.productDetailsList\" :key=\"productDetails.$abHashCode\">\n					<td>{{index+1}}</td>\n					<td v-ab-permission=\"permission.businessopportunity.productDetails.productName\">\n						<ab-custom-dialog v-model=\"productDetails.productName\" placeholder=\"请输入产品名称\" :permission=\"scopePermission.productName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-产品名称【第\'+(index+1)+\'条】\'\" dialog-key=\"selectproduct\" :object-mapping=\"productDetails\" :value-mapping=\"{productName:\'productName\',specificationAndModel:\'specificationAndModel\',unit:\'unit\',price:\'price\'}\" :dialog-setting=\"{ multiple: 0}\" :show-detail=\"false\"></ab-custom-dialog>\n					</td>\n					<td v-ab-permission=\"permission.businessopportunity.productDetails.specificationAndModel\">\n						<ab-input v-model=\"productDetails.specificationAndModel\" placeholder=\"请输入规格型号\" :permission=\"scopePermission.specificationAndModel\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-规格型号【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.businessopportunity.productDetails.unit\">\n						<ab-tree-select v-model=\"productDetails.unit\" placeholder=\"请输入单位\" :permission=\"scopePermission.unit\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-单位【第\'+(index+1)+\'条】\'\" :disabled=\"true\" dic-code=\"productunit\" :multiple=\"false\"></ab-tree-select>\n					</td>\n					<td v-ab-permission=\"permission.businessopportunity.productDetails.price\">\n						<ab-number v-model=\"productDetails.price\" placeholder=\"请输入价格\" :permission=\"scopePermission.price\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-单价(元)【第\'+(index+1)+\'条】\'\" :disabled=\"true\" :comdify=\"true\"></ab-number>\n					</td>\n					<td v-ab-permission=\"permission.businessopportunity.productDetails.quantity\">\n						<ab-number v-model=\"productDetails.quantity\" placeholder=\"请输入数量\" :permission=\"scopePermission.quantity\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-数量【第\'+(index+1)+\'条】\'\"></ab-number>\n					</td>\n					<td v-ab-permission=\"permission.businessopportunity.productDetails.zkfs\">\n						<ab-select v-model=\"productDetails.zkfs\" placeholder=\"请输入折扣方式\" :permission=\"scopePermission.zkfs\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-折扣方式【第\'+(index+1)+\'条】\'\" :options=\"[{\'key\':\'1\',\'text\':\'由金额计算\'},{\'key\':\'2\',\'text\':\'由折扣计算\'}]\"></ab-select>\n					</td>\n					<td v-ab-permission=\"permission.businessopportunity.productDetails.discount\">\n						<ab-number v-model=\"productDetails.discount\" placeholder=\"请输入折扣\" :permission=\"scopePermission.discount\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-折扣【第\'+(index+1)+\'条】\'\" coin-value=\"%\"></ab-number>\n					</td>\n					<td v-ab-permission=\"permission.businessopportunity.productDetails.subtotal\">\n						<ab-number v-model=\"productDetails.subtotal\" placeholder=\"请输入小计\" :permission=\"scopePermission.subtotal\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-小计(元)【第\'+(index+1)+\'条】\'\" coin-value=\"￥\" :comdify=\"true\"></ab-number>\n					</td>\n					<td>\n						<ab-button-group>\n							<ab-sub-del v-model=\"data.businessopportunity.productDetailsList\" :index=\"index\" :permission=\"scopeTablePermission.businessopportunity.productDetails\">移除</ab-sub-del>\n						</ab-button-group>\n						<abTablePlugins>\n							<ab-calculate v-model=\"productDetails.subtotal\" :script=\"abGetNumber(productDetails.price)*abGetNumber(productDetails.quantity)*abGetNumber(productDetails.discount)*0.01\" v-if=\"productDetails.zkfs==2\" desc=\"计算小计\" :decimals=\"2\"></ab-calculate>\n							<ab-dyn-perm v-model=\"productDetails\" table-code=\"productDetails\" :parent-data=\"data.businessopportunity\" parent-code=\"businessOpportunity\" :data=\"data.businessopportunity\" v-model:permission=\"scopePermission\" :config=\"[{&quot;column&quot;:[&quot;productDetails.subtotal&quot;],&quot;rights&quot;:&quot;r&quot;,&quot;valCol&quot;:&quot;productDetails.zkfs&quot;,&quot;valColType&quot;:&quot;varchar&quot;,&quot;cond&quot;:&quot;eq&quot;,&quot;recove&quot;:true,&quot;valColRelType&quot;:&quot;oneToMany&quot;,&quot;sn&quot;:1,&quot;children&quot;:[],&quot;parentSn&quot;:&quot;&quot;,&quot;logic&quot;:&quot;and&quot;,&quot;isJs&quot;:false,&quot;js&quot;:&quot;&quot;,&quot;condVal&quot;:&quot;2&quot;},{&quot;column&quot;:[&quot;productDetails.discount&quot;],&quot;rights&quot;:&quot;r&quot;,&quot;valCol&quot;:&quot;productDetails.zkfs&quot;,&quot;valColType&quot;:&quot;varchar&quot;,&quot;cond&quot;:&quot;eq&quot;,&quot;recove&quot;:true,&quot;valColRelType&quot;:&quot;oneToMany&quot;,&quot;sn&quot;:2,&quot;children&quot;:[],&quot;parentSn&quot;:&quot;&quot;,&quot;logic&quot;:&quot;and&quot;,&quot;isJs&quot;:false,&quot;js&quot;:&quot;&quot;,&quot;condVal&quot;:&quot;1&quot;}]\"></ab-dyn-perm>\n							<ab-calculate v-model=\"productDetails.discount\" :script=\"abGetNumber(productDetails.subtotal)/(abGetNumber(productDetails.price)*abGetNumber(productDetails.quantity))*100\" v-if=\"productDetails.zkfs==1\" desc=\"计算折扣\" :decimals=\"2\"></ab-calculate>\n						</abTablePlugins>\n					</td>\n				</ab-sub-tr-scope>\n			</tbody>\n		</table>\n	</ab-card>\n	<ab-form-item :span=\"24\" label=\"合计总额\" :permission=\"permission.businessopportunity.businessOpportunity.totalAmount\">\n		<ab-number v-model=\"data.businessopportunity.totalAmount\" placeholder=\"请输入合计总额\" :permission=\"permission.businessopportunity.businessOpportunity.totalAmount\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-合计总额\" :disabled=\"true\" :comdify=\"true\"></ab-number>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"折扣方式\" :permission=\"permission.businessopportunity.businessOpportunity.zkfs\">\n		<ab-radio-group v-model=\"data.businessopportunity.zkfs\" placeholder=\"请输入折扣方式\" :permission=\"permission.businessopportunity.businessOpportunity.zkfs\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-折扣方式\" :options=\"[{\'key\':\'1\',\'text\':\'由金额计算\'},{\'key\':\'2\',\'text\':\'由折扣计算\'}]\"></ab-radio-group>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"12\" label=\"整单折扣比例\" :permission=\"permission.businessopportunity.businessOpportunity.discount\">\n		<ab-number v-model=\"data.businessopportunity.discount\" placeholder=\"请输入折扣\" :permission=\"permission.businessopportunity.businessOpportunity.discount\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-整单折扣比例\" coin-value=\"%\"></ab-number>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"最终报价\" :permission=\"permission.businessopportunity.businessOpportunity.finalPrice\">\n		<ab-number v-model=\"data.businessopportunity.finalPrice\" placeholder=\"请输入最终价格\" :permission=\"permission.businessopportunity.businessOpportunity.finalPrice\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"商机-最终报价\" coin-value=\"￥\" :comdify=\"true\" :convert-currency=\"true\"></ab-number>\n	</ab-form-item>\n</ab-form-group>\n<abTablePlugins>\n	<ab-calculate v-model=\"data.businessopportunity.totalAmount\" :script=\"abSubSum(data.businessopportunity.productDetailsList,\'subtotal\')\" desc=\"计算明细总金额\" :decimals=\"2\"></ab-calculate>\n	<ab-calculate v-model=\"data.businessopportunity.finalPrice\" :script=\"abGetNumber(data.businessopportunity.totalAmount)*abGetNumber(data.businessopportunity.discount)*0.01\" v-if=\"data.businessopportunity.zkfs==2\" desc=\"计算整单折扣后的报价\" :decimals=\"2\"></ab-calculate>\n	<ab-custom-query dialog-key=\"onearticle\" v-model=\"data.businessopportunity\" :value-mapping=\"{contactName:\'customerContact\'}\" :immediate=\"false\" :mapping-init-data=\"initData.businessopportunity.businessOpportunity\" :param=\"{enterprise_name_$VEQ:data.businessopportunity.customerName}\" required-params=\"enterprise_name_$VEQ\"></ab-custom-query>\n	<ab-calculate v-model=\"data.businessopportunity.discount\" :script=\"abGetNumber(data.businessopportunity.finalPrice)/abGetNumber(data.businessopportunity.totalAmount)*100\" v-if=\"data.businessopportunity.zkfs==1\" desc=\"计算折扣\" :decimals=\"2\"></ab-calculate>\n	<ab-dyn-perm v-model=\"data.businessopportunity\" table-code=\"businessOpportunity\" :data=\"data.businessopportunity\" v-model:permission=\"permission.businessopportunity\" :config=\"[{&quot;column&quot;:[&quot;businessOpportunity.discount&quot;],&quot;rights&quot;:&quot;r&quot;,&quot;valCol&quot;:&quot;businessOpportunity.zkfs&quot;,&quot;valColType&quot;:&quot;varchar&quot;,&quot;cond&quot;:&quot;eq&quot;,&quot;recove&quot;:true,&quot;valColRelType&quot;:&quot;main&quot;,&quot;sn&quot;:1,&quot;children&quot;:[],&quot;parentSn&quot;:&quot;&quot;,&quot;logic&quot;:&quot;and&quot;,&quot;isJs&quot;:false,&quot;js&quot;:&quot;&quot;,&quot;condVal&quot;:&quot;1&quot;},{&quot;column&quot;:[&quot;businessOpportunity.finalPrice&quot;],&quot;rights&quot;:&quot;r&quot;,&quot;valCol&quot;:&quot;businessOpportunity.zkfs&quot;,&quot;valColType&quot;:&quot;varchar&quot;,&quot;cond&quot;:&quot;eq&quot;,&quot;recove&quot;:true,&quot;valColRelType&quot;:&quot;main&quot;,&quot;sn&quot;:2,&quot;children&quot;:[],&quot;parentSn&quot;:&quot;&quot;,&quot;logic&quot;:&quot;and&quot;,&quot;isJs&quot;:false,&quot;js&quot;:&quot;&quot;,&quot;condVal&quot;:&quot;2&quot;}]\"></ab-dyn-perm>\n</abTablePlugins>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	console.log(\"脚本将会混入自定义表单组件中...\");\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){  \n			// 执行业务校验，return false则终止提交 \n			return true;  \n		}\n	}\n }', 'design', '2023-08-03 09:24:26', '1602918114232172634', '1602918114232172544', '2024-01-20 13:10:46', '1602918114232172634', 0);
INSERT INTO `biz_form` VALUES ('1810507437883740160', 'pc', 'addingclues_V5_pc', '个人线索_不必填', 'crm', 'addingclues_V5', 'elementFlowDesign', 'newcustomers', '新增客户', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-divider content-position=\"left\">客户信息</ab-divider>\n	<ab-form-item :span=\"8\" label=\"客户名称\" :permission=\"permission.newcustomers.customerInformation.customerName\">\n		<ab-input v-model=\"data.newcustomers.customerName\" placeholder=\"请输入客户名称\" :permission=\"permission.newcustomers.customerInformation.customerName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索_不必填-客户名称\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"线索阶段\" :permission=\"permission.newcustomers.customerInformation.customerstage\">\n		<ab-select v-model=\"data.newcustomers.customerstage\" placeholder=\"请输入客户阶段\" :permission=\"permission.newcustomers.customerInformation.customerstage\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索_不必填-线索阶段\" :options=\"[{\'key\':\'1\',\'text\':\'新增线索\'},{\'key\':\'2\',\'text\':\'领取线索\'},{\'key\':\'3\',\'text\':\'退回线索\'}]\"></ab-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"线索来源\" :permission=\"permission.newcustomers.customerInformation.customerSource\">\n		<ab-tree-select v-model=\"data.newcustomers.customerSource\" placeholder=\"请输入客户来源\" :permission=\"permission.newcustomers.customerInformation.customerSource\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索_不必填-线索来源\" dic-code=\"sourcesofclues\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"标签\" :permission=\"permission.newcustomers.customerInformation.label\">\n		<ab-tree-select v-model=\"data.newcustomers.label\" placeholder=\"请输入标签\" :permission=\"permission.newcustomers.customerInformation.label\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索_不必填-标签\" dic-code=\"label\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"所属行业\" :permission=\"permission.newcustomers.customerInformation.industry\">\n		<ab-select v-model=\"data.newcustomers.industry\" placeholder=\"请输入所属行业\" :permission=\"permission.newcustomers.customerInformation.industry\" :rules=\"[{\'max\':255,\'message\':\'最多可输入255个字符\'}]\" desc=\"个人线索_不必填-所属行业\" dic-code=\"industry\"></ab-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"线索池\" :permission=\"permission.newcustomers.customerInformation.cluePool\">\n		<ab-tree-select v-model=\"data.newcustomers.cluePool\" placeholder=\"请输入线索池\" :permission=\"permission.newcustomers.customerInformation.cluePool\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索_不必填-线索池\" dic-code=\"regionaldivision\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"线索详情\" :permission=\"permission.newcustomers.customerInformation.demand\">\n		<ab-input v-model=\"data.newcustomers.demand\" placeholder=\"请输入线索详情\" :permission=\"permission.newcustomers.customerInformation.demand\" :rules=\"[]\" desc=\"个人线索_不必填-线索详情\" type=\"textarea\" rows=\"3\"></ab-input>\n	</ab-form-item>\n	<ab-card style=\"margin-bottom: 15px;width: 100%\" shadow=\"hover\" body-style=\"overflow:auto\" v-ab-permission=\"tablePermission.newcustomers.contactInformation\">\n		<template #header>\n			<span class=\"title\">联系人信息</span>\n			<ab-sub-load v-model=\"data.newcustomers\" table-path=\"contactInformationList\" bo-code=\"newcustomers\" :permission-type=\"permissionType\" :permission-value=\"permissionValue\" :permission=\"tablePermission.newcustomers.contactInformation\" fk=\"id,id\"></ab-sub-load>\n			<ab-sub-add class=\"el-button el-button--primary\" v-model=\"data.newcustomers.contactInformationList\" :init-data=\"initData.newcustomers.contactInformation\" :permission=\"tablePermission.newcustomers.contactInformation\" :init-first-row=\"true\">添加</ab-sub-add>\n		</template>\n		<table class=\"ab-table\">\n			<thead>\n				<tr>\n					<th class=\"ab-table-sn\">序号</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.decisionMakerOrNot\" ><ab-required :permission=\"permission.newcustomers.contactInformation.decisionMakerOrNot\"></ab-required>是否决策人</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.contactName\" ><ab-required :permission=\"permission.newcustomers.contactInformation.contactName\"></ab-required>姓名</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.mobilePhoneNumber\" ><ab-required :permission=\"permission.newcustomers.contactInformation.mobilePhoneNumber\"></ab-required>手机号</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.post\" ><ab-required :permission=\"permission.newcustomers.contactInformation.post\"></ab-required>职务</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.wechatSignal\" ><ab-required :permission=\"permission.newcustomers.contactInformation.wechatSignal\"></ab-required>微信号</th>\n					<th v-ab-permission=\"permission.newcustomers.contactInformation.mailbox\" ><ab-required :permission=\"permission.newcustomers.contactInformation.mailbox\"></ab-required>邮箱</th>\n					<th>操作</th>\n				</tr>\n			</thead>\n			<tbody>\n				<ab-sub-tr-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.newcustomers.contactInformation\" :table-permission=\"tablePermission\" v-for=\"(contactInformation,index) in data.newcustomers.contactInformationList\" :key=\"contactInformation.$abHashCode\">\n					<td>{{index+1}}</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.decisionMakerOrNot\">\n						<ab-switch v-model=\"contactInformation.decisionMakerOrNot\" :permission=\"scopePermission.decisionMakerOrNot\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-是否决策人【第\'+(index+1)+\'条】\'\" active-text=\"是\" inactive-text=\"否\" active-value=\"1\" inactive-value=\"0\"></ab-switch>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.contactName\">\n						<ab-input v-model=\"contactInformation.contactName\" placeholder=\"请输入联系人姓名\" :permission=\"scopePermission.contactName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-姓名【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.mobilePhoneNumber\">\n						<ab-input v-model=\"contactInformation.mobilePhoneNumber\" placeholder=\"请输入手机号\" :permission=\"scopePermission.mobilePhoneNumber\" :rules=\"[{\'pattern\':\'((\\\\d{11})|^((\\\\d{7,8})|(\\\\d{4}|\\\\d{3})-(\\\\d{7,8})|(\\\\d{4}|\\\\d{3})-(\\\\d{7,8})-(\\\\d{4}|\\\\d{3}|\\\\d{2}|\\\\d{1})|(\\\\d{7,8})-(\\\\d{4}|\\\\d{3}|\\\\d{2}|\\\\d{1}))$)\',\'message\':\'请输入正确的手机号码\'},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-手机号【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.post\">\n						<ab-input v-model=\"contactInformation.post\" placeholder=\"请输入职务\" :permission=\"scopePermission.post\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-职务【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.wechatSignal\">\n						<ab-input v-model=\"contactInformation.wechatSignal\" placeholder=\"请输入微信号\" :permission=\"scopePermission.wechatSignal\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-微信号【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td v-ab-permission=\"permission.newcustomers.contactInformation.mailbox\">\n						<ab-input v-model=\"contactInformation.mailbox\" placeholder=\"请输入邮箱\" :permission=\"scopePermission.mailbox\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'联系人信息-邮箱【第\'+(index+1)+\'条】\'\"></ab-input>\n					</td>\n					<td>\n						<ab-button-group>\n							<ab-sub-del v-model=\"data.newcustomers.contactInformationList\" :index=\"index\" :permission=\"scopeTablePermission.newcustomers.contactInformation\">移除</ab-sub-del>\n						</ab-button-group>\n					</td>\n				</ab-sub-tr-scope>\n			</tbody>\n		</table>\n	</ab-card>\n	<ab-form-item :span=\"12\" label=\"客户经理\" :permission=\"permission.newcustomers.customerInformation.responsibleperson\">\n		<ab-data-selector v-model=\"data.newcustomers.responsibleperson\" placeholder=\"请输入客户经理\" :permission=\"permission.newcustomers.customerInformation.responsibleperson\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"个人线索_不必填-客户经理\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"user\" param=\"userId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n</ab-form-group>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	console.log(\"脚本将会混入自定义表单组件中...\");\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){  \n			// 执行业务校验，return false则终止提交 \n			return true;  \n		}\n	}\n }', 'design', '2023-12-01 17:14:58', '1602918114232172634', '', '2023-12-29 18:05:48', '1602918114232172634', 0);
INSERT INTO `biz_form` VALUES ('1810507439586627584', 'pc', 'tianjiahuikuai_pc', '添加回款', 'crm', 'tianjiahuikuai', 'elementFlowDesign', 'contractmanagement', '合同管理', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-form-item :span=\"12\" label=\"合同标题\" :permission=\"permission.contractmanagement.contractmanagement.contractTitle\">\n		<ab-custom-dialog v-model=\"data.contractmanagement.contractTitle\" placeholder=\"请输入合同标题\" :permission=\"permission.contractmanagement.contractmanagement.contractTitle\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-合同标题\" dialog-key=\"contractQuery\" :object-mapping=\"data.contractmanagement\" :value-mapping=\"{contractTitle:\'contractTitle\',contractnumber:\'contractnumber\',customerID:\'customerID\',contractStatus:\'contractStatus\'}\" :dialog-setting=\"{ multiple: 0}\" :param=\"{responsibleperson_$VEQ:data.contractmanagement.responsibleperson}\" :show-detail=\"false\"></ab-custom-dialog>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"合同编号\" :permission=\"permission.contractmanagement.contractmanagement.contractnumber\">\n		<ab-serial-no v-model=\"data.contractmanagement.contractnumber\" placeholder=\"请输入合同编号\" :permission=\"permission.contractmanagement.contractmanagement.contractnumber\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-合同编号\" :disabled=\"true\" serial-no-code=\"contractnumber\"></ab-serial-no>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"客户名称\" :permission=\"permission.contractmanagement.contractmanagement.customerID\">\n		<ab-data-selector v-model=\"data.contractmanagement.customerID\" placeholder=\"请输入客户名称\" :permission=\"permission.contractmanagement.contractmanagement.customerID\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-客户名称\" dialog-key=\"selectingCustomers\" label-field=\"customerName\" value-field=\"id\" select-type=\"custom\" param=\"id_\" :dialog-setting=\"{ multiple: 0}\" :dialog-param=\"{responsibleperson_$VEQ:data.contractmanagement.responsibleperson}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"合同状态\" :permission=\"permission.contractmanagement.contractmanagement.contractStatus\">\n		<ab-tree-select v-model=\"data.contractmanagement.contractStatus\" placeholder=\"请输入合同状态\" :permission=\"permission.contractmanagement.contractmanagement.contractStatus\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-合同状态\" dic-code=\"contractStatus\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"合同签订日期\" :permission=\"permission.contractmanagement.contractmanagement.contractsigningdate\">\n		<ab-date v-model=\"data.contractmanagement.contractsigningdate\" placeholder=\"请输入合同签订日期\" :permission=\"permission.contractmanagement.contractmanagement.contractsigningdate\" :rules=\"[]\" desc=\"合同管理-合同签订日期\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n	</ab-form-item>\n	<ab-card style=\"margin-bottom: 15px;width: 100%\" shadow=\"hover\" body-style=\"overflow:auto\" v-ab-permission=\"tablePermission.contractmanagement.collectionplan\">\n		<template #header>\n			<span class=\"title\">添加回款</span>\n			<ab-sub-load v-model=\"data.contractmanagement\" table-path=\"collectionplanList\" bo-code=\"contractmanagement\" :permission-type=\"permissionType\" :permission-value=\"permissionValue\" :permission=\"tablePermission.contractmanagement.collectionplan\" fk=\"customerID\"></ab-sub-load>\n			<ab-sub-add class=\"el-button el-button--primary\" v-model=\"data.contractmanagement.collectionplanList\" :init-data=\"initData.contractmanagement.collectionplan\" :permission=\"tablePermission.contractmanagement.collectionplan\" :init-first-row=\"true\">添加</ab-sub-add>\n		</template>\n		<ab-sub-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.contractmanagement.collectionplan\" :table-permission=\"tablePermission\" v-for=\"(collectionplan,index) in data.contractmanagement.collectionplanList\" :key=\"collectionplan.$abHashCode\">\n			<ab-sub-del v-model=\"data.contractmanagement.collectionplanList\" :index=\"index\" :permission=\"scopeTablePermission.contractmanagement.collectionplan\">移除</ab-sub-del>\n			<abTablePlugins>\n				<ab-custom-query dialog-key=\"collectionplan\" v-model=\"collectionplan\" :value-mapping=\"{plannedpaymentcollectiontime:\'plannedpaymentcollectiontime\',plannedpaymentamount:\'plannedpaymentamount\',invoicingamount:\'invoicingamount\',invoicingtime:\'invoicingtime\',collectionamount:\'collectionamount\',paymentcollectiontime:\'paymentcollectiontime\',state:\'state\',invoiceattachment:\'invoiceattachment\'}\" :immediate=\"false\" :param=\"{customer_i_d_$VEQ:data.contractmanagement.customerID,payment_$VEQ:collectionplan.payment}\" required-params=\"payment_$VEQ\"></ab-custom-query>\n			</abTablePlugins>\n			<ab-form-group>\n				<ab-form-item :span=\"24\" label=\"款项\" :permission=\"scopePermission.payment\">\n					<ab-select v-model=\"collectionplan.payment\" placeholder=\"选择第几笔付款\" :permission=\"scopePermission.payment\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'回款计划-款项【第\'+(index+1)+\'条】\'\" :options=\"[{\'key\':\'1\',\'text\':\'第一笔\'},{\'key\':\'2\',\'text\':\'第二笔\'},{\'key\':\'3\',\'text\':\'第三笔\'},{\'key\':\'4\',\'text\':\'第四笔\'}]\"></ab-select>\n				</ab-form-item>\n				<ab-form-item :span=\"12\" label=\"计划回款金额\" :permission=\"scopePermission.plannedpaymentamount\">\n					<ab-number v-model=\"collectionplan.plannedpaymentamount\" placeholder=\"请输入计划回款金额\" :permission=\"scopePermission.plannedpaymentamount\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'回款计划-计划回款金额【第\'+(index+1)+\'条】\'\"></ab-number>\n				</ab-form-item>\n				<ab-form-item :span=\"12\" label=\"计划回款时间\" :permission=\"scopePermission.plannedpaymentcollectiontime\">\n					<ab-date v-model=\"collectionplan.plannedpaymentcollectiontime\" placeholder=\"请输入计划回款时间\" :permission=\"scopePermission.plannedpaymentcollectiontime\" :rules=\"[]\" :desc=\"\'回款计划-计划回款时间【第\'+(index+1)+\'条】\'\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n				</ab-form-item>\n				<ab-form-item :span=\"12\" label=\"开票金额\" :permission=\"scopePermission.invoicingamount\">\n					<ab-number v-model=\"collectionplan.invoicingamount\" placeholder=\"请输入开票金额\" :permission=\"scopePermission.invoicingamount\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'回款计划-开票金额【第\'+(index+1)+\'条】\'\"></ab-number>\n				</ab-form-item>\n				<ab-form-item :span=\"12\" label=\"开票时间\" :permission=\"scopePermission.invoicingtime\">\n					<ab-date v-model=\"collectionplan.invoicingtime\" placeholder=\"请输入开票时间\" :permission=\"scopePermission.invoicingtime\" :rules=\"[]\" :desc=\"\'回款计划-开票时间【第\'+(index+1)+\'条】\'\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n				</ab-form-item>\n				<ab-form-item :span=\"12\" label=\"回款金额\" :permission=\"scopePermission.collectionamount\">\n					<ab-number v-model=\"collectionplan.collectionamount\" placeholder=\"请输入回款金额\" :permission=\"scopePermission.collectionamount\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'回款计划-回款金额【第\'+(index+1)+\'条】\'\" :comdify=\"true\"></ab-number>\n				</ab-form-item>\n				<ab-form-item :span=\"12\" label=\"回款时间\" :permission=\"scopePermission.paymentcollectiontime\">\n					<ab-date v-model=\"collectionplan.paymentcollectiontime\" placeholder=\"请输入回款时间\" :permission=\"scopePermission.paymentcollectiontime\" :rules=\"[]\" :desc=\"\'回款计划-回款时间【第\'+(index+1)+\'条】\'\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n				</ab-form-item>\n				<ab-form-item :span=\"12\" label=\"状态\" :permission=\"scopePermission.state\">\n					<ab-tree-select v-model=\"collectionplan.state\" placeholder=\"请输入状态\" :permission=\"scopePermission.state\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'回款计划-状态【第\'+(index+1)+\'条】\'\" dic-code=\"paymentstatus\" :multiple=\"false\"></ab-tree-select>\n				</ab-form-item>\n				<ab-form-item :span=\"12\" label=\"发票或收据\" :permission=\"scopePermission.invoiceattachment\">\n					<ab-upload v-model=\"collectionplan.invoiceattachment\" :permission=\"scopePermission.invoiceattachment\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'回款计划-发票或收据【第\'+(index+1)+\'条】\'\" list-type=\"text\" dic-code=\"ywfj\" :multiple=\"true\"></ab-upload>\n				</ab-form-item>\n			</ab-form-group>\n		</ab-sub-scope>\n	</ab-card>\n	<ab-form-item :span=\"12\" label=\"负责人\" :permission=\"permission.contractmanagement.contractmanagement.responsibleperson\">\n		<ab-data-selector v-model=\"data.contractmanagement.responsibleperson\" placeholder=\"请输入负责人\" :permission=\"permission.contractmanagement.contractmanagement.responsibleperson\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-负责人\" :disabled=\"true\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"custom\" param=\"userId\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n</ab-form-group>\n<abTablePlugins>\n	<ab-custom-query dialog-key=\"businessOpportunityCustomers\" v-model=\"data.contractmanagement\" :value-mapping=\"{opportunityName:\'opportunityName\',客户编号:\'customernumber\'}\" :immediate=\"false\" :param=\"{负责人$VEQ:data.contractmanagement.responsibleperson,customerNameID$VEQ:data.contractmanagement.customerID}\"></ab-custom-query>\n</abTablePlugins>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n    	console.log(\"脚本将会混入自定义表单组件中...\");\n	},\n	methods:{\n		testaaa : function(){\n			alert(1)\n		},\n		custValid:function(){  \n			// 执行业务校验，return false则终止提交 \n			return true;  \n		}\n	}\n }', 'design', '2023-10-19 18:12:28', '1602918114232172634', '1602918114232172544', '2023-12-29 17:42:56', '1602918114232172634', 0);
