INSERT INTO `biz_form` VALUES ('1810507441495035904', 'pc', 'contractmanagement_pc', '合同管理', 'crm', 'contractmanagement', 'elementFlowDesign', 'contractmanagement', '合同管理', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-form-item :span=\"12\" label=\"合同标题\" :permission=\"permission.contractmanagement.contractmanagement.contractTitle\">\n		<ab-input v-model=\"data.contractmanagement.contractTitle\" placeholder=\"请输入合同标题\" :permission=\"permission.contractmanagement.contractmanagement.contractTitle\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-合同标题\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"合同编号\" :permission=\"permission.contractmanagement.contractmanagement.contractnumber\">\n		<ab-serial-no v-model=\"data.contractmanagement.contractnumber\" placeholder=\"请输入合同编号\" :permission=\"permission.contractmanagement.contractmanagement.contractnumber\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-合同编号\" :disabled=\"true\" serial-no-code=\"contractnumber\"></ab-serial-no>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"客户名称\" :permission=\"permission.contractmanagement.contractmanagement.customerID\">\n		<ab-data-selector v-model=\"data.contractmanagement.customerID\" placeholder=\"请输入客户名称\" :permission=\"permission.contractmanagement.contractmanagement.customerID\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-客户名称\" dialog-key=\"selectingCustomers\" label-field=\"customerName\" value-field=\"id\" select-type=\"custom\" param=\"id_\" :dialog-setting=\"{ multiple: 0}\" :dialog-param=\"{responsibleperson_$VEQ:data.contractmanagement.responsibleperson}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"客户编号\" :permission=\"permission.contractmanagement.contractmanagement.customernumber\">\n		<ab-input v-model=\"data.contractmanagement.customernumber\" placeholder=\"请输入客户编号\" :permission=\"permission.contractmanagement.contractmanagement.customernumber\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-客户编号\" :disabled=\"true\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"商机名称\" :permission=\"permission.contractmanagement.contractmanagement.opportunityName\">\n		<ab-input v-model=\"data.contractmanagement.opportunityName\" placeholder=\"请输入商机名称\" :permission=\"permission.contractmanagement.contractmanagement.opportunityName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-商机名称\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"合同状态\" :permission=\"permission.contractmanagement.contractmanagement.contractStatus\">\n		<ab-tree-select v-model=\"data.contractmanagement.contractStatus\" placeholder=\"请输入合同状态\" :permission=\"permission.contractmanagement.contractmanagement.contractStatus\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"合同管理-合同状态\" dic-code=\"contractStatus\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"合同签订日期\" :permission=\"permission.contractmanagement.contractmanagement.contractsigningdate\">\n		<ab-date v-model=\"data.contractmanagement.contractsigningdate\" placeholder=\"请输入合同签订日期\" :permission=\"permission.contractmanagement.contractmanagement.contractsigningdate\" :rules=\"[]\" desc=\"合同管理-合同签订日期\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"合同到期日期\" :permission=\"permission.contractmanagement.contractmanagement.contractexpirationdate\">\n		<ab-date v-model=\"data.contractmanagement.contractexpirationdate\" placeholder=\"请输入合同到期日期\" :permission=\"permission.contractmanagement.contractmanagement.contractexpirationdate\" :rules=\"[]\" desc=\"合同管理-合同到期日期\" type=\"date\" format=\"YYYY-MM-DD\" :min=\"data.contractmanagement.contractsigningdate\"></ab-date>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"要货日期\" :permission=\"permission.contractmanagement.contractmanagement.yhrq\">\n		<ab-date v-model=\"data.contractmanagement.yhrq\" placeholder=\"请输入要货日期\" :permission=\"permission.contractmanagement.contractmanagement.yhrq\" :rules=\"[]\" desc=\"合同管理-要货日期\" type=\"date\" format=\"YYYY-MM-DD\"></ab-date>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"产品设计稿\" :permission=\"permission.contractmanagement.contractmanagement.cpsjg\">\n		<ab-upload v-model=\"data.contractmanagement.cpsjg\" :permission=\"permission.contractmanagement.contractmanagement.cpsjg\" :rules=\"[]\" desc=\"合同管理-产品设计稿\" list-type=\"text\" dic-code=\"ywfj\"></ab-upload>\n	</ab-form-item>\n	<ab-tabs model-value=\"1\" class=\"demo-tabs\" style=\"width: 100%;\" type=\"\">\n		<ab-tab-pane label=\"货物详情\" name=\"1\">\n			<ab-form-group>\n				<ab-card style=\"margin-bottom: 15px;width: 100%\" shadow=\"hover\" body-style=\"overflow:auto\" v-ab-permission=\"tablePermission.contractmanagement.productDetails\">\n					<template #header>\n						<span class=\"title\">产品明细</span>\n						<ab-sub-load v-model=\"data.contractmanagement\" table-path=\"productDetailsList\" bo-code=\"contractmanagement\" :permission-type=\"permissionType\" :permission-value=\"permissionValue\" :permission=\"tablePermission.contractmanagement.productDetails\" fk=\"customerID\"></ab-sub-load>\n						<ab-sub-add class=\"el-button el-button--primary\" v-model=\"data.contractmanagement.productDetailsList\" :init-data=\"initData.contractmanagement.productDetails\" :permission=\"tablePermission.contractmanagement.productDetails\" :init-first-row=\"true\">添加</ab-sub-add>\n					</template>\n					<table class=\"ab-table\">\n						<thead>\n							<tr>\n								<th class=\"ab-table-sn\">序号</th>\n								<th v-ab-permission=\"permission.contractmanagement.productDetails.productName\" ><ab-required :permission=\"permission.contractmanagement.productDetails.productName\"></ab-required>产品名称</th>\n								<th v-ab-permission=\"permission.contractmanagement.productDetails.specificationAndModel\" ><ab-required :permission=\"permission.contractmanagement.productDetails.specificationAndModel\"></ab-required>规格型号</th>\n								<th v-ab-permission=\"permission.contractmanagement.productDetails.unit\" ><ab-required :permission=\"permission.contractmanagement.productDetails.unit\"></ab-required>单位</th>\n								<th v-ab-permission=\"permission.contractmanagement.productDetails.price\" ><ab-required :permission=\"permission.contractmanagement.productDetails.price\"></ab-required>单价(元)</th>\n								<th v-ab-permission=\"permission.contractmanagement.productDetails.quantity\" ><ab-required :permission=\"permission.contractmanagement.productDetails.quantity\"></ab-required>数量</th>\n								<th v-ab-permission=\"permission.contractmanagement.productDetails.zkfs\" ><ab-required :permission=\"permission.contractmanagement.productDetails.zkfs\"></ab-required>折扣方式</th>\n								<th v-ab-permission=\"permission.contractmanagement.productDetails.discount\" ><ab-required :permission=\"permission.contractmanagement.productDetails.discount\"></ab-required>折扣</th>\n								<th v-ab-permission=\"permission.contractmanagement.productDetails.subtotal\" ><ab-required :permission=\"permission.contractmanagement.productDetails.subtotal\"></ab-required>小计(元)</th>\n								<th>操作</th>\n							</tr>\n						</thead>\n						<tbody>\n							<ab-sub-tr-scope v-slot=\"{scopePermission, scopeTablePermission}\" :permission=\"permission.contractmanagement.productDetails\" :table-permission=\"tablePermission\" v-for=\"(productDetails,index) in data.contractmanagement.productDetailsList\" :key=\"productDetails.$abHashCode\">\n								<td>{{index+1}}</td>\n								<td v-ab-permission=\"permission.contractmanagement.productDetails.productName\">\n									<ab-custom-dialog v-model=\"productDetails.productName\" placeholder=\"请输入产品名称\" :permission=\"scopePermission.productName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-产品名称【第\'+(index+1)+\'条】\'\" dialog-key=\"selectproduct\" search-desc=\"选择产品\" :object-mapping=\"productDetails\" :value-mapping=\"{productName:\'productName\',specificationAndModel:\'specificationAndModel\',unit:\'unit\',price:\'price\'}\" :dialog-setting=\"{ multiple: 0}\" :mapping-init-data=\"initData.contractmanagement.productDetails\" :show-detail=\"false\" detail-form-code=\"productmaintenance_pc\"></ab-custom-dialog>\n								</td>\n								<td v-ab-permission=\"permission.contractmanagement.productDetails.specificationAndModel\">\n									<ab-input v-model=\"productDetails.specificationAndModel\" placeholder=\"请输入规格型号\" :permission=\"scopePermission.specificationAndModel\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-规格型号【第\'+(index+1)+\'条】\'\"></ab-input>\n								</td>\n								<td v-ab-permission=\"permission.contractmanagement.productDetails.unit\">\n									<ab-tree-select v-model=\"productDetails.unit\" placeholder=\"请输入单位\" :permission=\"scopePermission.unit\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-单位【第\'+(index+1)+\'条】\'\" dic-code=\"productunit\" :multiple=\"false\"></ab-tree-select>\n								</td>\n								<td v-ab-permission=\"permission.contractmanagement.productDetails.price\">\n									<ab-number v-model=\"productDetails.price\" placeholder=\"请输入单价(元)\" :permission=\"scopePermission.price\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-单价(元)【第\'+(index+1)+\'条】\'\" :disabled=\"true\"></ab-number>\n								</td>\n								<td v-ab-permission=\"permission.contractmanagement.productDetails.quantity\">\n									<ab-number v-model=\"productDetails.quantity\" placeholder=\"请输入数量\" :permission=\"scopePermission.quantity\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-数量【第\'+(index+1)+\'条】\'\"></ab-number>\n								</td>\n								<td v-ab-permission=\"permission.contractmanagement.productDetails.zkfs\">\n									<ab-select v-model=\"productDetails.zkfs\" placeholder=\"请输入折扣方式\" :permission=\"scopePermission.zkfs\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-折扣方式【第\'+(index+1)+\'条】\'\" :options=\"[{\'key\':\'1\',\'text\':\'以金额计算\'},{\'key\':\'2\',\'text\':\'以折扣计算\'}]\"></ab-select>\n								</td>\n								<td v-ab-permission=\"permission.contractmanagement.productDetails.discount\">\n									<ab-number v-model=\"productDetails.discount\" placeholder=\"请输入折扣\" :permission=\"scopePermission.discount\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-折扣【第\'+(index+1)+\'条】\'\" coin-value=\"%\"></ab-number>\n								</td>\n								<td v-ab-permission=\"permission.contractmanagement.productDetails.subtotal\">\n									<ab-number v-model=\"productDetails.subtotal\" placeholder=\"请输入小计(元)\" :permission=\"scopePermission.subtotal\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" :desc=\"\'产品明细-小计(元)【第\'+(index+1)+\'条】\'\" :comdify=\"true\"></ab-number>\n								</td>\n								<td>\n									<ab-button-group>\n										<ab-sub-del v-model=\"data.contractmanagement.productDetailsList\" :index=\"index\" :permission=\"scopeTablePermission.contractmanagement.productDetails\">移除</ab-sub-del>\n									</ab-button-group>\n									<abTablePlugins>\n										<ab-calculate v-model=\"productDetails.subtotal\" :script=\"abGetNumber(productDetails.price)*abGetNumber(productDetails.quantity)*abGetNumber(productDetails.discount)*0.01\" v-if=\"productDetails.zkfs==2\" desc=\"计算小计\" :decimals=\"2\"></ab-calculate>\n										<ab-calculate v-model=\"productDetails.discount\" :script=\"abGetNumber(productDetails.subtotal)/(abGetNumber(productDetails.price)*abGetNumber(productDetails.quantity))*100\" v-if=\"productDetails.zkfs==1\" desc=\"计算折扣\" :decimals=\"3\"></ab-calculate>\n										<ab-dyn-perm v-model=\"productDetails\" table-code=\"productDetails\" :parent-data=\"data.contractmanagement\" parent-code=\"contractmanagement\" :data=\"data.contractmanagement\" v-model:permission=\"scopePermission\" :config=\"[{&quot;column&quot;:[&quot;productDetails.discount&quot;],&quot;rights&quot;:&quot;r&quot;,&quot;valCol&quot;:&quot;productDetails.zkfs&quot;,&quot;valColType&quot;:&quot;varchar&quot;,&quot;cond&quot;:&quot;eq&quot;,&quot;recove&quot;:true,&quot;valColRelType&quot;:&quot;oneToMany&quot;,&quot;sn&quot;:1,&quot;children&quot;:[],&quot;parentSn&quot;:&quot;&quot;,&quot;logic&quot;:&quot;and&quot;,&quot;isJs&quot;:false,&quot;js&quot;:&quot;&quot;,&quot;condVal&quot;:&quot;1&quot;},{&quot;column&quot;:[&quot;productDetails.subtotal&quot;],&quot;rights&quot;:&quot;r&quot;,&quot;valCol&quot;:&quot;productDetails.zkfs&quot;,&quot;valColType&quot;:&quot;varchar&quot;,&quot;cond&quot;:&quot;eq&quot;,&quot;recove&quot;:true,&quot;valColRelType&quot;:&quot;oneToMany&quot;,&quot;sn&quot;:2,&quot;children&quot;:[],&quot;parentSn&quot;:&quot;&quot;,&quot;logic&quot;:&quot;and&quot;,&quot;isJs&quot;:false,&quot;js&quot;:&quot;&quot;,&quot;condVal&quot;:&quot;2&quot;}]\"></ab-dyn-perm>\n									</abTablePlugins>\n								</td>\n							</ab-sub-tr-scope>\n						</tbody>\n					</table>\n				</ab-card>\n				<ab-form-item :span=\"8\" label=\"合计\" :permission=\"permission.contractmanagement.contractmanagement.total\">\n					<ab-number v-model=\"data.contractmanagement.total\" placeholder=\"请输入合计\" :permission=\"permission.contractmanagement.contractmanagement.total\" :rules=\"[{\'max\':8,\'message\':\'最多可输入8个字符\'}]\" desc=\"合同管理-合计\" :disabled=\"true\" coin-value=\"￥\"></ab-number>\n				</ab-form-item>\n				<ab-form-item :span=\"8\" label=\"折扣\" :permission=\"permission.contractmanagement.contractmanagement.discount\">\n					<ab-number v-model=\"data.contractmanagement.discount\" placeholder=\"请输入折扣\" :permission=\"permission.contractmanagement.contractmanagement.discount\" :rules=\"[{\'max\':8,\'message\':\'最多可输入8个字符\'}]\" desc=\"合同管理-折扣\" coin-value=\"%\"></ab-number>\n				</ab-form-item>\n				<ab-form-item :span=\"8\" label=\"折扣方式\" :permission=\"permission.contractmanagement.contractmanagement.zkfs\">\n			