INSERT INTO `biz_form` VALUES ('1810507442761715712', 'pc', 'customerfollowup_pc', '客户跟进', 'crm', 'customerfollowup', 'elementFlowDesign', 'followup', '跟进', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-form-item :span=\"24\" label=\"跟进类型\" :permission=\"permission.followup.followUpRecords.followuptype\">\n		<ab-radio-group v-model=\"data.followup.followuptype\" placeholder=\"请输入跟进类型\" :permission=\"permission.followup.followUpRecords.followuptype\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户跟进-跟进类型\" :options=\"[{\'key\':\'1\',\'text\':\'正常跟进\'},{\'key\':\'2\',\'text\':\'计划跟进\'}]\"></ab-radio-group>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"客户\" :permission=\"permission.followup.followUpRecords.followUpRecords\">\n		<ab-data-selector v-model=\"data.followup.followUpRecords\" placeholder=\"请输入客户\" :permission=\"permission.followup.followUpRecords.followUpRecords\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户跟进-客户\" dialog-key=\"selectingCustomers\" label-field=\"customerName\" value-field=\"id\" select-type=\"custom\" param=\"id_\" icon=\"endorsement\" :dialog-setting=\"{ multiple: 0}\" :show-detail=\"true\" detail-form-code=\"addCustomer_pc\" :dialog-param=\"{responsibleperson_$VEQ:data.followup.followupPerson}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"商机名称\" :permission=\"permission.followup.followUpRecords.opportunityName\">\n		<ab-data-selector v-model=\"data.followup.opportunityName\" placeholder=\"请输入商机名称\" :permission=\"permission.followup.followUpRecords.opportunityName\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户跟进-商机名称\" dialog-key=\"businessOpportunityCustomers\" label-field=\"opportunityName\" value-field=\"opportunityId\" select-type=\"custom\" param=\"opportunity_id_\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"24\" label=\"联系人\" :permission=\"permission.followup.followUpRecords.contacts\">\n		<ab-custom-dialog v-model=\"data.followup.contacts\" placeholder=\"请输入联系人\" :permission=\"permission.followup.followUpRecords.contacts\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户跟进-联系人\" dialog-key=\"selectcontacts\" search-desc=\"选择联系人\" :object-mapping=\"data.followup\" :value-mapping=\"{contactName:\'contacts\'}\" :dialog-setting=\"{ multiple: 0}\" :param=\"{enterprise_name_$VEQ:data.followup.followUpRecords}\" :show-detail=\"false\"></ab-custom-dialog>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"沟通方式\" :permission=\"permission.followup.followUpRecords.followUpMethod\">\n		<ab-select v-model=\"data.followup.followUpMethod\" placeholder=\"请输入沟通方式\" :permission=\"permission.followup.followUpRecords.followUpMethod\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户跟进-沟通方式\" dic-code=\"contactinformation\"></ab-select>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"跟进内容\" :permission=\"permission.followup.followUpRecords.followUpContent\">\n		<ab-input v-model=\"data.followup.followUpContent\" placeholder=\"请输入跟进内容\" :permission=\"permission.followup.followUpRecords.followUpContent\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户跟进-跟进内容\" type=\"textarea\" rows=\"3\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"计划跟进时间\" :permission=\"permission.followup.followUpRecords.followUpTime\">\n		<ab-date v-model=\"data.followup.followUpTime\" placeholder=\"请输入计划跟进时间\" :permission=\"permission.followup.followUpRecords.followUpTime\" :rules=\"[]\" desc=\"客户跟进-计划跟进时间\" type=\"datetime\" format=\"YYYY-MM-DD HH:mm:ss\" min=\"${currentDateTime}\"></ab-date>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"跟进时间\" :permission=\"permission.followup.followUpRecords.currenttime\">\n		<ab-date v-model=\"data.followup.currenttime\" placeholder=\"请输入跟进时间\" :permission=\"permission.followup.followUpRecords.currenttime\" :rules=\"[]\" desc=\"客户跟进-跟进时间\" :disabled=\"true\" type=\"datetime\" format=\"YYYY-MM-DD HH:mm:ss\"></ab-date>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"状态\" :permission=\"permission.followup.followUpRecords.state\">\n		<ab-select v-model=\"data.followup.state\" placeholder=\"请输入状态\" :permission=\"permission.followup.followUpRecords.state\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户跟进-状态\" :options=\"[{\'key\':\'1\',\'text\':\'未跟进\'},{\'key\':\'2\',\'text\':\'已跟进\'},{\'key\':\'3\',\'text\':\'已超时\'}]\"></ab-select>\n	</ab-form-item>\n	<ab-form-item :span=\"12\" label=\"跟进人\" :permission=\"permission.followup.followUpRecords.followupPerson\">\n		<ab-data-selector v-model=\"data.followup.followupPerson\" placeholder=\"请输入跟进人\" :permission=\"permission.followup.followUpRecords.followupPerson\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户跟进-跟进人\" dialog-key=\"userSelector\" label-field=\"name\" value-field=\"id\" select-type=\"custom\" param=\"userId\" icon=\"referee\" :dialog-setting=\"{ multiple: 0}\"></ab-data-selector>\n	</ab-form-item>\n	<ab-form-item :span=\"24\" label=\"备注\" :permission=\"permission.followup.followUpRecords.remarks\">\n		<ab-input v-model=\"data.followup.remarks\" placeholder=\"请输入计划备注等额外信息\" :permission=\"permission.followup.followUpRecords.remarks\" :rules=\"[{\'max\':500,\'message\':\'最多可输入500个字符\'}]\" desc=\"客户跟进-备注\" type=\"textarea\" rows=\"2\"></ab-input>\n	</ab-form-item>\n</ab-form-group>', 'window.custFormComponentMixin = {\n	data: function () {\n   		return {\"user\":{\"name\":\"张珊\"}};\n    },\n    created : function(){\n      // 自动设置跟进项目\n     \n	},\n	methods:{\n		\n		custValid:function(){  \n			// 执行业务校验，return false则终止提交 \n			return true;  \n		}\n	},\n  watch: {\n    \"data.followup.state\": function(newValue, oldValue){\n        this.calUpTime();\n    }\n}\n }', 'design', '2023-10-14 13:38:15', '1602918114232172634', '1602918114232172544', '2024-03-22 15:50:07', '1602918114232172634', 0);
