INSERT INTO `biz_form` VALUES ('1810507444552683520', 'pc', 'addCustomer_V2_pc', '客户编辑详情页', 'crm', 'addCustomer_V2', 'elementFlowDesign', 'newcustomers', '新增客户', '<ab-form-global-setting :label-width=\"120\" :readonlyShowText=\"false\" label-suffix=\"：\"/>\n<ab-form-group>\n	<ab-form-item :span=\"24\" :label-width=\"0\">\n		<ab-divider content-position=\"left\">客户信息</ab-divider>\n	</ab-form-item>\n	<ab-form-item class=\"is-required\" :span=\"8\" label=\"客户名称\" :permission=\"permission.newcustomers.customerInformation.customerName\">\n		<ab-input v-model=\"data.newcustomers.customerName\" placeholder=\"请输入客户名称\" :permission=\"permission.newcustomers.customerInformation.customerName\" :rules=\"[{\'message\':\'必填\',\'required\':true},{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户编辑详情页-客户名称\"></ab-input>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"客户编号\" :permission=\"permission.newcustomers.customerInformation.customernumber\">\n		<ab-serial-no v-model=\"data.newcustomers.customernumber\" placeholder=\"请输入客户编号\" :permission=\"permission.newcustomers.customerInformation.customernumber\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户编辑详情页-客户编号\" serial-no-code=\"customernumber\"></ab-serial-no>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"客户阶段\" :permission=\"permission.newcustomers.customerInformation.customerstage1\">\n		<ab-tree-select v-model=\"data.newcustomers.customerstage1\" placeholder=\"请输入客户阶段\" :permission=\"permission.newcustomers.customerInformation.customerstage1\" :rules=\"[{\'max\':50,\'message\':\'最多可输入50个字符\'}]\" desc=\"客户编辑详情页-客户阶段\" dic-code=\"customerstage\" :multiple=\"false\"></ab-tree-select>\n	</ab-form-item>\n	<ab-form-item :span=\"8\" label=\"标签\" :permission=\"permission.newcustomers.customerInformation.label\">\n		<ab-select v-model=\"data.newcustomers.label\" placeholder=\"请输入标签\" :permission=\"permission.newcustomers.customerInformation.label\" :rules=\"[{\'max\':100,\'message\':\'最多可输入100个字符\'}]\" 