INSERT INTO `biz_form_design` VALUES ('1810507447115403264', 'customerdetails', 'addCustomer_V1', '客户信息顶部', '', 'newcustomers', '新增客户', 'byBo', 'pc', '{\"column\":[{\"type\":\"title\",\"title\":\"标题\",\"span\":24,\"fixSpan\":true,\"display\":true,\"fontSize\":20,\"text\":\"标题\",\"labelWidth\":\"0px\",\"position\":\"left\",\"prop\":\"ab169744509737856816\"},{\"type\":\"dataSelector\",\"title\":\"客户经理\",\"label\":\"客户经理\",\"span\":6,\"display\":true,\"maxlength\":50,\"decimal\":0,\"code\":\"responsibleperson\",\"defaultValue\":\"\",\"rules\":[],\"fieldType\":\"varchar\",\"readOnly\":false,\"tableCode\":\"customerInformation\",\"prop\":\"ab169535287298971142\",\"dataSelectorConfig\":{\"multiple\":0,\"searchDesc\":\"\",\"mappingFields\":[],\"objectMapping\":\"data.newcustomers\",\"params\":{},\"paramsDefaultValue\":{},\"dialogKey\":\"userSelector\",\"selectType\":\"custom\",\"valueField\":\"id\",\"labelField\":\"name\",\"param\":\"userId\",\"labelColumn\":\"fullName\",\"dialogName\":\"用户选择\"}},{\"type\":\"serialno\",\"title\":\"客户编号\",\"label\":\"客户编号\",\"span\":6,\"display\":true,\"maxlength\":50,\"decimal\":0,\"placeholder\":\"请输入客户编号\",\"code\":\"customernumber\",\"defaultValue\":\"\",\"rules\":[],\"fieldType\":\"varchar\",\"readOnly\":false,\"tableCode\":\"customerInformation\",\"prop\":\"ab169043095043182776\",\"serialCode\":\"customernumber\",\"serialName\":\"客户编号\"},{\"type\":\"treeSelect\",\"title\":\"所属行业\",\"label\":\"所属行业\",\"span\":6,\"display\":true,\"maxlength\":50,\"decimal\":0,\"code\":\"industry\",\"defaultValue\":\"\",\"rules\":[],\"fieldType\":\"varchar\",\"readOnly\":false,\"tableCode\":\"customerInformation\",\"prop\":\"ab16974454796514785\",\"multiple\":false,\"dicCode\":\"industry\",\"dicCodeName\":\"行业\",\"dicNodeSelect\":[{\"id\":\"1684105116961550336\",\"parentId\":\"1684104229761396736\",\"code\":\"agricultureforestryanimalhusbandryandfishery\",\"name\":\"农、林、牧、渔业\",\"dictKey\":\"industry\",\"typeCode\":\"crm\",\"sn\":1,\"dictType\":\"node\",\