INSERT INTO `biz_object` VALUES ('1810507429591601152', 'newcustomers', '客户线索', NULL, '{\"children\":[{\"children\":[],\"tableCode\":\"productDetails\",\"tableComment\":\"产品明细\",\"type\":\"oneToMany\",\"fks\":[{\"from\":\"customerName\",\"type\":\"parentField\",\"value\":\"id\"}],\"sync\":true},{\"children\":[],\"tableCode\":\"contactInformation\",\"tableComment\":\"联系信息\",\"type\":\"oneToMany\",\"fks\":[{\"from\":\"enterpriseName\",\"type\":\"parentField\",\"value\":\"id\"}],\"sync\":true},{\"children\":[],\"tableCode\":\"followUpRecords\",\"tableComment\":\"跟进记录\",\"type\":\"oneToMany\",\"fks\":[{\"from\":\"followUpRecords\",\"type\":\"parentField\",\"value\":\"id\"}],\"sync\":true}],\"tableCode\":\"customerInformation\",\"tableComment\":\"客户信息\",\"type\":\"main\",\"sync\":true}', 'crm', 'db', '{}', 1, '2023-07-26 15:17:03', '1602918114232172634', '1602918114232172544', '2024-07-09 10:53:08', '1602918114232172634', ',customerInformation,productDetails,contactInformation,followUpRecords,', '[{\"id\":1,\"alias\":\"save\",\"name\":\"保存\",\"script\":\"\",\"desc\":\"系统默认,保存接口\",\"params\":[{\"name\":\"data\",\"required\":true}],\"defualt\":true},{\"id\":2,\"alias\":\"delete\",\"name\":\"删除\",\"script\":\"\",\"desc\":\"系统默认,删除接口\",\"params\":[{\"name\":\"id\",\"required\":true}],\"defualt\":true},{\"id\":3,\"alias\":\"get\",\"name\":\"获取数据\",\"script\":\"import com.dstz.biz.object.persistence.BizData\\nimport cn.hutool.core.thread.ThreadUtil;\\n\\n  \\n\\tdef cust = new BizData(\\\"newcustomers\\\",id)\\n\\tString lxr = cust.get(\\\"lxr\\\");\\n  def contactInformationList =  cust.getChildren(\\\"contactInformation\\\");\\n\\n  if(contactInformationList.isEmpty() && lxr != null){\\n    BizData suBizData = cust.addChildren(\\\"contactInformation\\\") ;\\n    suBizData.set(\\\"contactName\\\",lxr)\\n    suBizData.set(\\\"mobilePhoneNumber\\\",cust.get(\\\"lxsj\\\"))\\n  }\\n  \\n  return cust;\",\"desc\":\"如果是导入的数据，则给数据填充下联系人\",\"params\":[{\"name\":\"id\",\"required\":true}],\"defualt\":true,\"flow\":true}]', 0);
