INSERT INTO `sys_script` VALUES ('1602918114232172599', '通过组织id 组织类型 角色 获取候选人', 'orgScript.getSpecificSuperPostIdentity(String groupId, int level, String roleCodes)\n', 'setCandidate', '用于流程人员脚本，通过组织id 组织类型 角色 设置候选人，Set<SysIdentity>', '2022-12-14 14:47:09', '1', '', '2023-04-13 16:24:31', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172619', '设置通过ID Name type 构建候选人', 'orgScript.constructeIdentity(String id, String name, String type)\n//orgScript.constructeIdentity(\"1\", \"管理员\",\"user\")', 'setCandidate', '用于流程人员脚本，通过ID Name type 构建候选人，Set<SysIdentity>', '2022-12-14 14:47:09', '1', '', '2023-04-13 16:24:19', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172637', '设置通过ID Name 构建候选人', 'orgScript.constructeIdentityUser(String id, String name)\n//orgScript.constructeIdentityUser(\"1\", \"管理员\")', 'setCandidate', '用于流程人员脚本，通过ID Name 构建候选人，Set<SysIdentity>', '2022-12-14 14:47:09', '1', '', '2023-04-13 16:23:50', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172659', '获取上级组织作为候选人', '// 发起人所在组织\n//String startOrgId = bpmInstance.getCreateOrgId();\n\n// groupId 若为null 则默认获取当前组织即 currentOrgId\nSet<SysIdentity> parentIdentity = orgScript.getSuperOrgIdentity(groupId);\n\n', 'setCandidate', '用于流程人员脚本，返回Set<SysIdentity>', '2022-12-14 14:47:09', '1', '', '2023-04-13 16:24:06', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172662', '获取指定类型的上级组织作为候选人', '// groupId 为组织ID，若为null 则使用当前组织，level为组织级别  集团0、分公司1、组织3、班组5\nSet<SysIdentity> group = orgScript.getSpecificSuperOrgIdentity(String groupId,int level)\n\n\n// 如获取发起人所在组织的分公司作为候选人\n//String startOrgId = bpmInstance.getCreateOrgId();\n//return getSpecificSuperOrgIdentity(startOrgId,1);', 'setCandidate', '用于流程人员脚本，返回指定类型组织的Set<SysIdentity>', '2022-12-14 14:47:09', '1', '', '2023-04-13 16:23:58', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172670', '根据角色条件获取角色候选组', '//orgScript.getRoleSis(String where)\n// 获取级别大于等于50 小于等于60：\norgScript.getRoleSis(\"level_ >= 50 and level_ <= 200\")', 'getGroupInformation', '根据角色条件获取角色候选组', '2022-12-14 14:47:09', '1', '', '2023-04-13 15:29:41', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172683', '根据id获取组信息', 'orgScript.getSis(String type, String... ids)\n//orgScript.getSis(\"user\", \"1\")\n//orgScript.getSis(\"org\", \"410054569125740545\")', 'getGroupInformation', '根据id获取组信息', '2022-12-14 14:47:09', '1', '', '2023-04-12 18:31:45', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172700', '获取指定类型的上级组织', 'orgScript.getSpecificSuperOrgIdentity(String groupId, int level)\n//组织id:为空则去当前用户所在组织的id\n//调用getSpecificSuperOrg(String groupId, int level)方法获取上级组织\n// 如获取当前分公司的组织\n//orgScript.getSpecificSuperOrg(null,0);\n', 'getGroupInformation', '如获取当前部门上级中 组织类型为分公司的组织\n即查询所属公司信息\n获取指定组织上级的人员返回SysIdentity对象的集合:接收String类型的groupId和int类型的level; 参考getSpecificSuperOrg(String groupId, int level)方法获取上级组织', '2022-12-14 14:47:09', '1', '', '2023-04-12 17:57:43', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172704', '获取某个岗位下的某些角色的人员列表', 'orgScript.getPostUserByGroupAndRole(String groupIds, String roleCodes)\n//groupIds:为空，则取当前用户所在组织的id\n//orgScript.getPostUserByGroupAndRole(\"\", \"yyzj\")', 'getGroupInformation', '获取某个岗位下的某些角色的人员列表返回SysIdentity集合:入参String类型的组织id，多个以“,”分隔；为空，则取当前用户所在主组织; String类型的角色编码，多个以“,”分隔', '2022-12-14 14:47:09', '1', '', '2023-04-12 18:31:58', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172709', '获取当前组织下的子组织', 'orgScript.getOrgChildrend()', 'getGroupInformation', '获取当前组织下的子组织返回组织id的集合', '2022-12-14 14:47:09', '1', '', '2023-04-12 17:15:12', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172718', '获取组织类型', '//orgId 若为 null 则获取当前组织\norgScript.getOrgLevel(orgId)\n\n// 获取流程发起人的组织级别\n//return orgScript.getOrgLevel(bpmInstance.getCreateOrgId())', 'getGroupInformation', '用来判断某个组织的组织类型（集团0、分公司1、部门3、班组5）返回Int', '2022-12-14 14:47:09', '1', '', '2023-04-12 15:08:24', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172721', '获取用户 角色/职务 级别', '// userId 若为null则获取当前用户\norgScript.getUserRoleLevel(userId);\n\n// 如，流程分支中判断 发起人的职级是否为副总50以上级别。\n//String startUserId = bpmInstance.getCreateBy();\n//return orgScript.getUserRoleLevel(startUserId)>50;\n', 'getGroupInformation', '获取用户 职级、角色级别，当有多个角色时，返回最大的职级。 返回 Int\n使用场景：如 部门经理(职级50)、副总(职级80)、普通员工(职级 20)不同角色他们拥有不同的级别。在请假流程中可以判断用户的职级，当大于某个值时作出对应的跳转', '2022-12-14 14:47:09', '1', '', '2023-04-12 15:07:51', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172728', '检查用户是否拥有某角色', 'orgScript.checkUserHasRole(String userId, String roleCode)\n//orgScript.checkUserHasRole(\"1\", \"jgs\")\n//用户id:为空，则取当前用户id\n//如判断用户是否为 部门负责人。返回Boolean', 'systemDefault', '检查用户是否拥有某角色:\n入参: userId 若为空则获取当前用户, roleCode 为角色编码\n返回: Boolean', '2022-12-14 14:47:09', '1', '', '2023-04-13 10:16:49', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172754', '指定数据通过一个sql 获取候选人', 'sysScript.getIdentityBySqlOnDataSource(String dataSourceKey,String sql, Object ... params)', 'getCandidatesSQL', '指定数据通过一个sql 获取候选人', '2022-12-14 14:47:09', '1', '', '2023-04-12 18:18:31', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172760', '通过一个sql 获取候选人', 'sysScript.getIdentityBySql(String sql, Object ... params)\n', 'getCandidatesSQL', '通过sql获取候选人用于流程节点通过脚本选择', '2022-12-14 14:47:09', '1', '', '2023-04-12 18:18:21', '超级管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172763', '指定数据源执行Count SQL更新语句', 'sysScript.executeIntegerSqlOnDataSource(String dataSourceKey,String sql, Object ... params)', 'executeSQL', '参数:\nsql：SQL 包含绑定的参数\nparams：SQL绑定的入参\n返回值:\nint : coun', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:43:13', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172766', '执行Count SQL更新语句', 'sysScript.executeIntegerSql(String sql, Object ... params)', 'executeSQL', '参数:\nsql：SQL 包含绑定的参数\nparams：SQL绑定的入参\n返回值:\nint : coun', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:42:08', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172769', '指定数据源执行SQL语句', '//dataSourceKey 系统数据源别名\nsysScript.executeUpdateSqlOnDataSource(String dataSourceKey,String sql, Object ... params)\n   ', 'executeSQL', '参数:\ndataSourceKey：数据源别名，可通过系统配置-数据源管理新增数据源，请确保数据源拥有更新权限\nsql：SQL 包含绑定的参数\nparams：SQL绑定的入参\n返回值:\nint: 成功更新条数\n警告： 请勿以外部数据源形式更新主数据源正在更新事物中的同一条业务数据，会导致数据库行锁。', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:41:45', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172772', '执行SQL更新语句', 'sysScript.executeUpdateSql(String sql, Object ... params);\n//用于流程事件中执行sql操作数据库;可根据外键更新指定字段的值\n//String sql = \"update org_user set fullname_ = ? where id_ = ? \";\n//sysScript.executeUpdateSql(sql,\"系统管理员\",\"1\");\n', 'executeSQL', '参数:\nsql：SQL 包含绑定的参数\nparams：SQL绑定的入参\n返回值:\nint : 更新条数', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:41:29', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172776', '获取当前用户姓名', 'sysScript.getCurrentUserName()', 'currentUser', '获取当前用户姓名', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:38:35', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172786', '获取当前用户组织名称', 'sysScript.getCurrentGroupName()', 'currentUser', '获取当前用户组织名称', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:38:17', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172788', '获取当前用户信息', 'sysScript.getCurrentUser().getFullName()', 'currentUser', '获取当前用户信息', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:38:07', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172791', '获取当前组织ID', 'import com.dstz.base.common.utils.UserContextUtils;\nreturn UserContextUtils.getGroupId();', 'currentUser', '通过引入静态方法来调用系统脚本，这样不需要实现Iscript脚本 。', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:37:56', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172793', '获取当前用户信息', 'sysScript.getCurrentUser().getFullName()', 'currentUser', '获取用户的某一个属性', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:37:41', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1602918114232172797', '根据别名获取下一个流水号', 'sysScript.getNextSerialNo(\"dayNo\");', 'systemDefault', '根据流水号别名获取下一个流水号', '2022-12-14 14:47:09', '1', '', '2023-04-12 14:24:30', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1645995316072837120', '根据别名和重编规则参数获取下一个流水号', 'Map<String, String> paramMap = new HashMap<>();\nparamMap.put(\"prefix\",\"AB-\");\nparamMap.put(\"suffix\",\"-BPM\")\nsysScript.getNextSerialNo(\"monthNum\",paramMap);', 'systemDefault', '参数paramMap支持设置多个重编规则；map-key为流水号重编规则的参数code设置；map-vaule用户根据需求设置', '2023-04-12 11:40:39', '1', '', '2023-04-12 14:30:38', '系统管理员', '1');
INSERT INTO `sys_script` VALUES ('1646038022367137792', '根据别名和重编规则参数获取下一个流水号', 'sysScript.getNextSerialNo(\"codeDayNo\",\'AB-\');', 'systemDefault', '参数param；会把param替换为流水号重编规则的参数code', '2023-04-12 14:30:21', '1', '', '2023-04-12 14:30:46', '系统管理员', '1');
